# Stories for albums 501–550 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220 words per story, three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_501_550.py; later edits: python3 tools/apply_stories.py stories_501_550
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(502, [
'''סימפל מיינדס באו מגלזגו שבסקוטלנד, וכבר בתחילת שנות השמונים הוציאו כמה אלבומים של פוסט־פאנק קר ואלקטרוני, שלא הגיעו לקהל רחב. ב־New Gold Dream, שיצא ב־1982, הם נשמעו פתאום חמים, רכים וחולמניים, והאלבום הגיע לעשירייה הראשונה במצעד הבריטי. הזמר ג׳ים קר, הגיטריסט צ׳רלי ברצ׳יל והקלידן מיק מקניל בנו יחד צליל שנשמע כמו אור שמש דרך ערפל.''',
'''הצליל עשוי שכבות: קלידים מנצנצים, גיטרה מהדהדת שכמעט לא מנגנת אקורדים, בס עמוק ומלודי ותופים יציבים. קר שר בקול רך ונלהב, ומילותיו מלאות בדימויים של קיץ, אור ותקווה, בלי סיפור ברור. Promised You a Miracle, הסינגל שפרץ, הוא שיר ריקוד אופטימי עם בס מקפץ. Glittering Prize נשמע כמו ניצחון קטן, ו־Someone Somewhere in Summertime, הפותח, הוא שיר געגועים רך. ב־Hunter and the Hunted מנגן סולו סינתיסייזר אורח מכובד במיוחד: נגן הג׳אז הרבי הנקוק. גם שיר הנושא, New Gold Dream, ארוך ומהפנט, כמו נסיעה בלילה.''',
'''האלבום הפך את סימפל מיינדס ללהקה גדולה, ופתח את הדרך להצלחה עולמית בשנים הבאות, עם Don't You (Forget About Me) מסרט הנעורים "מועדון ארוחת הבוקר", ועם הופעות באצטדיונים. רבים רואים באלבום הזה את הרגע היפה והעדין ביותר שלהם, לפני שהצליל שלהם נעשה גדול ורועש.''',
'''זה אלבום של אווירה. שמעו אותו ברצף, בנסיעה או בערב, ותנו לשכבות לעטוף אתכם. ואם אהבתם את Crocodiles של אקו והבאנימן (אלבום 462), תשמעו כאן שכנים סקוטים, רכים וחלומיים יותר.''',
], [
('Promised You a Miracle', 'הסינגל שפרץ, שיר ריקוד אופטימי עם בס מקפץ וקלידים מנצנצים.'),
('Someone Somewhere in Summertime', 'הפותח, שיר געגועים רך כמו ערב קיץ שלא נגמר.'),
('Hunter and the Hunted', 'שיר מהפנט, עם סולו סינתיסייזר אורח של נגן הג׳אז הרבי הנקוק.'),
])

add(503, [
'''מדנס באו מקמדן שבצפון לונדון, ובסוף שנות השבעים היו חלק מגל הסקא הבריטי של חברת 2 Tone, לצד הספשלס (אלבום 453). עם השנים הם הפכו לאחת הלהקות האהובות באנגליה, עם קליפים מצחיקים, ריקוד "רכבת" מפורסם וזמר בשם סאגס. The Rise & Fall, שיצא ב־1982, הוא האלבום הבוגר שלהם, והפיקו אותו קלייב לאנגר ואלן וינסטנלי, שהפיקו באותה שנה גם את Too-Rye-Ay (אלבום 501).''',
'''האלבום עוסק בילדות, בזיכרונות ובשכונה, כמעט כמו ספר סיפורים על לונדון של מעמד הפועלים. המוזיקה כבר לא רק סקא: יש בה פופ בריטי של שנות השישים, מוזיקת אולמות ישנה, כלי נשיפה, פסנתר וקצב קופצני. Our House, הלהיט הגדול, הוא תמונה חמה ומצחיקה של משפחה רגילה בבית צפוף: אבא שמתלבש לעבודה, אמא שמגהצת, וילדים שרבים. Tomorrow's (Just Another Day) מתאר שגרה עצובה, ושיר הנושא מספר על חזרה לשכונת הילדות, שבה הכל השתנה. Primrose Hill מעט חלומי ומוזר, ו־Blue Skinned Beast עוסק ברמז במלחמת פוקלנד שהתנהלה באותה שנה.''',
'''Our House הפך לאחד השירים המזוהים עם אנגליה של שנות השמונים, והיה גם ההצלחה הגדולה היחידה של מדנס באמריקה. האלבום הראה שלהקה שהתחילה בבדיחות וריקודים יודעת גם לכתוב שירים עמוקים ונוגים על החיים. הלהקה צילמה לשירים קליפים מצחיקים, שבהם חבריה מתחפשים ומשחקים כמו בקומדיה.''',
'''שמעו את Our House, ואחריו את Tomorrow's (Just Another Day). אותה להקה, אותו צליל, ושני צדדים של אותם חיים: החום המשפחתי, והשגרה האפורה.''',
], [
('Our House', 'תמונה חמה ומצחיקה של משפחה רגילה בבית צפוף, הלהיט הגדול שלהם.'),
("Tomorrow's (Just Another Day)", 'שגרה עצובה של יום אחרי יום, בקצב קופצני ומבלבל.'),
('Rise and Fall', 'חזרה לשכונת הילדות, שבה כבר הכל השתנה, שיר נוגה ויפה.'),
])

add(504, [
'''דונלד פייגן היה חצי מסטילי דן (אלבומים 245, 290, 322 ו־379), הצמד שידע לכתוב פופ מתוחכם מלא ג׳אז וציניות. כשהצמד נפרד, פייגן הוציא ב־1982 אלבום סולו ראשון, The Nightfly, שבו חזר לילדותו בפרברי ניו ג׳רזי של סוף שנות החמישים. הוא היה אז נער שמאזין בלילה לתחנות ג׳אז ברדיו, וחולם על עתיד מבריק של מכוניות מעופפות ומסעות לחלל.''',
'''הצליל מבריק ונקי במיוחד: נגני אולפן מעולים, פסנתר חשמלי, כלי נשיפה, תופים מדויקים ושירה מחויכת ואירונית של פייגן. זה היה גם אחד האלבומים הראשונים שהוקלטו כולם בטכנולוגיה דיגיטלית חדשה, ויש בו צלילות מיוחדת. I.G.Y., הפותח, נקרא על שם "שנת הגאופיזיקה הבינלאומית" של 1957, ומתאר בחיוך את האופטימיות של אז, כשנדמה היה שהמדע יפתור הכל. New Frontier מספר על מסיבה של נערים במקלט אטומי, בזמן המלחמה הקרה. שיר הנושא מתאר שדרן רדיו לילי, שמנגן ג׳אז לנדודי השינה של העיר, ו־Maxine הוא שיר אהבה רך ומלא הרמוניות.''',
'''The Nightfly נחשב לאחד האלבומים המלוטשים בתולדות הפופ, ומשמש עד היום אולפנים וחנויות לבדיקת מערכות שמע. פייגן עצמו לא מיהר: האלבום הבא שלו יצא רק כעשר שנים אחר כך. הוא גם מכתב אהבה מתוק־מר לעתיד שהיה פעם, ולילדות שבה הכל עוד היה אפשרי.''',
'''אם אהבתם את Aja של סטילי דן (אלבום 379), זה ההמשך הטבעי. שמעו אותו בשקט ובאוזניות טובות, ושימו לב לעטיפה: פייגן בתור שדרן רדיו, עם סיגריה ותקליט של ג׳אז ליד המיקרופון.''',
], [
('I.G.Y.', 'האופטימיות של שנות החמישים, כשנדמה היה שהמדע יפתור הכל.'),
('New Frontier', 'מסיבת נערים במקלט אטומי, בזמן המלחמה הקרה, בקצב קליל ומחויך.'),
('The Nightfly', 'שדרן רדיו לילי שמנגן ג׳אז לנדודי השינה של העיר.'),
])

add(505, [
'''ניק הייווד היה בחור צעיר ונאה מפרבר דרומי של לונדון, שאהב פאנק, ג׳אז לטיני ופופ קליל. עם חבריו הוא הקים את הרקאט וואן האנדרד, להקה שלבשה סוודרים צמריים וחולצות מכופתרות במקום עור שחור. Pelican West, האלבום הראשון והיחיד שלהם עם הייווד, יצא ב־1982 והגיע למקום השני במצעד הבריטי.''',
'''המוזיקה עליזה ומקפצת: גיטרה פאנקית ונקייה, בס קופצני, כלי הקשה לטיניים, חצוצרה וסקסופון, והקול הנערי של הייווד, ששר על אהבה, על בגדים ועל קיץ. כמעט כל שיר נשמע כמו יום חופש שמשי. Love Plus One, הלהיט הגדול, הוא שיר אהבה עליז ומבלבל עם מקצב לטיני. Favourite Shirts (Boy Meets Girl), הפותח, מספר על נער שפוגש נערה במסיבה, בקצב מהיר וחוגג. Fantastic Day הוא שיר אופטימי על יום שבו הכל מצליח, ו־Lemon Firebrigade ו־Marine Boy מוזרים ומשעשעים, עם מילים כמעט חסרות היגיון.''',
'''האלבום היה הצלחה גדולה, אבל זמן קצר אחר כך הייווד עזב את הלהקה, והיא לא הצליחה בלעדיו. הוא המשיך בקריירת סולו. Pelican West נשאר רגע קטן ומאושר של הפופ הבריטי של תחילת שנות השמונים, כשלהקות חיפשו דרכים חדשות לרקוד אחרי הפאנק, ולבשו בגדים צבעוניים במקום עור שחור ומסמרות.''',
'''זה אלבום ליום שמש, לנסיעה או לבוקר עצל. שמעו אותו ברצף, ואם אהבתם, נסו את C'est Chic של שיק (אלבום 423), שממנו למדו הרבה להקות כמו זו איך לנגן גיטרה פאנקית.''',
], [
('Love Plus One', 'הלהיט הגדול, שיר אהבה עליז ומבלבל עם מקצב לטיני וחצוצרות.'),
('Favourite Shirts (Boy Meets Girl)', 'נער פוגש נערה במסיבה, בקצב מהיר וחוגג עם כלי הקשה.'),
('Fantastic Day', 'שיר אופטימי על יום שבו הכל מצליח, עם גיטרה פאנקית.'),
])

add(506, [
'''קייט בוש הייתה בת תשע־עשרה בלבד כשהגיעה למקום הראשון במצעד הבריטי עם Wuthering Heights ב־1978. ארבע שנים אחר כך היא כבר הפיקה בעצמה את אלבומה הרביעי, The Dreaming, והחליטה לעשות בדיוק מה שהיא רוצה: אלבום מוזר, צפוף, תיאטרלי ומלא ניסויים. השמיעה הראשונה בלבלה רבים, והוא נחשב לאלבום הקשה ביותר שלה.''',
'''בוש השתמשה בסינתיסייזר חדש בשם פיירלייט, שיכול לנגן כל צליל שהוקלט, לצד תופים חזקים, כלים אירים ממסורת עממית, דידג׳רידו אוסטרלי ושכבות רבות של קולות שלה עצמה, שצועקים, לוחשים וצוחקים. כל שיר הוא כמו סרט קצר. Sat in Your Lap, הפותח, עוסק ברצון לדעת הכל מיד, בלי ללמוד. Pull Out the Pin מספר על חייל במלחמת וייטנאם מנקודת המבט של הצד השני. Houdini מתאר את אשתו של הקוסם הארי הודיני, שמנסה ליצור איתו קשר אחרי מותו, ו־Suspended in Gaffa עוסק ברצון להגיע לשלמות ולא להצליח. Get Out of My House, בהשראת ספר האימה "הניצוץ", נשמע כמו בית רדוף.''',
'''האלבום לא נמכר טוב כמו קודמיו, אבל עם השנים הוא הפך לאחד האהובים על מוזיקאים, שראו בו הוכחה שאפשר לעשות פופ אמיץ ומוזר לחלוטין. בוש עצמה למדה ממנו איך להפיק, והאלבום הבא שלה, Hounds of Love, הפך להצלחה גדולה.''',
'''זה אלבום שדורש סבלנות. התחילו ב־Houdini, אחר כך Suspended in Gaffa, ורק אז שמעו את הכל ברצף. ואת קולה תשמעו גם בשיר של פיטר גבריאל (אלבום 459).''',
], [
('Houdini', 'אשתו של הקוסם המת מנסה לדבר איתו מעבר לקבר, דרמטי ומצמרר.'),
('Suspended in Gaffa', 'הרצון להגיע לשלמות ולא להצליח, בקצב מתנדנד כמעט כמו ואלס.'),
('Sat in Your Lap', 'פתיחה רועמת עם תופים כבדים, על הרצון לדעת הכל מיד.'),
])

add(507, [
'''אורנג׳ ג׳וס באו מגלזגו, והיו מהלהקות הראשונות של חברת התקליטים הקטנה Postcard, שהתחילה את מה שנקרא אחר כך "רוק אינדי". הזמר אדווין קולינס כתב שירים רומנטיים ומלאי הומור, ושר בקול עמוק ומעט מגומגם, כמו זמר קרונר שהתבלבל. Rip It Up, האלבום השני שלהם, יצא ב־1982, אחרי שההרכב השתנה, ונכנסו אליו המתופף זיקה מאניקה מזימבבואה והגיטריסט מלקולם רוס.''',
'''הצליל הוא חיבור מפתיע בין גיטרות נקיות ומצלצלות, כמו של הבירדס, לבין דיסקו ופאנק אמריקאי, כמו של שיק (אלבומים 423 ו־437). שיר הנושא, שהגיע לעשירייה הראשונה במצעד הבריטי, בנוי על קו בס חשמלי ומקפץ של מכונה קטנה בשם TB-303, מהשימושים המוקדמים שלה בשיר פופ, הרבה לפני שהפכה לצליל של מוזיקת האסיד האוס. קולינס שר בו על הצורך לקרוע הכל ולהתחיל מחדש. Breakfast Time קליל ומצחיק, I Can't Help Myself הוא שיר אהבה מתוק ומבויש, ו־Flesh of My Flesh שמח ומלא כלי נשיפה. בשירים של מאניקה, כמו Hokoyo, נכנסים גם קצבים אפריקאיים.''',
'''Rip It Up היה ההצלחה הגדולה של הלהקה, שהתפרקה כעבור שנתיים. קולינס המשיך לקריירת סולו, ושנים אחר כך הצליח בכל העולם עם A Girl Like You. משפט מהשיר, "לקרוע ולהתחיל מחדש", הפך לשם של ספר ידוע על תקופת הפוסט־פאנק, כי הוא מתאר בדיוק את הרוח של אותם ימים.''',
'''שמעו את שיר הנושא, ושימו לב לקו הבס המקפץ שמתחת לגיטרה. אחר כך שמעו את Le Freak או את I Want Your Love של שיק, ותבינו מאיפה באה ההשראה.''',
], [
('Rip It Up', 'לקרוע הכל ולהתחיל מחדש, עם קו בס חשמלי ומקפץ שהקדים את זמנו.'),
("I Can't Help Myself", 'שיר אהבה מתוק ומבויש, עם גיטרות מצלצלות וכלי נשיפה.'),
('Breakfast Time', 'שיר קליל ומצחיק על בוקר, עם קצב פאנקי וקולו העמוק של קולינס.'),
])

add(508, [
'''אחרי ההצלחה של Off the Wall (אלבום 450), מייקל ג׳קסון רצה לעשות את האלבום הגדול ביותר אי פעם, ולא פחות. הוא שוב עבד עם המפיק קווינסי ג׳ונס, ויחד בחרו כמה מהשירים הטובים מתוך עשרות שהוקלטו. Thriller יצא בסוף 1982 והפך לאלבום הנמכר ביותר בכל הזמנים, עם הערכות של עשרות מיליוני עותקים. שבעה משיריו נכנסו לעשירייה הראשונה במצעד האמריקאי.''',
'''באלבום יש כמעט הכל: פאנק, דיסקו, רוק, בלדות ופופ, והכל מלוטש ומדויק. Billie Jean, עם קו הבס המפורסם שלו, מספר על אישה שטוענת שג׳קסון הוא אבי ילדה, והוא מכחיש בפחד ובכעס. Beat It הוא שיר רוק נגד אלימות של כנופיות, עם סולו גיטרה של אדי ואן היילן (אלבום 415). שיר הנושא הוא סרט אימה מוזיקלי, עם קולו המצמרר של השחקן וינסנט פרייס בסוף, ו־Wanna Be Startin' Somethin', הפותח, הוא פאנק ארוך וסוחף שמסתיים בשירה אפריקאית. Human Nature הוא בלדה רכה ויפה על עיר בלילה, ו־The Girl Is Mine הוא דואט קליל עם פול מקרטני.''',
'''Thriller שינה את עולם המוזיקה. הקליפים שלו, ובמיוחד סרט האימה הקצר של Thriller, הפכו את הקליפ לאמנות בפני עצמה, וג׳קסון היה מהאמנים השחורים הראשונים שהוצגו בהרחבה ב־MTV. ב־1983 הוא הציג בטלוויזיה את צעד הריקוד "מונווק" בזמן Billie Jean, ונהיה לכוכב הגדול בעולם.''',
'''את השירים מהאלבום כמעט כולם מכירים, אז נסו לשמוע אותו ברצף, כמו אלבום. שימו לב לבס ב־Billie Jean ולמעבר החד בין הבלדות לבין שירי הריקוד.''',
], [
('Billie Jean', 'קו בס מפורסם ושיר מתוח על אישה שטוענת שהוא האב.'),
('Beat It', 'רוק נגד אלימות כנופיות, עם סולו גיטרה של אדי ואן היילן.'),
('Human Nature', 'בלדה רכה ויפה על עיר בלילה, עם סינתיסייזרים חלומיים.'),
])

add(509, [
'''הבירת׳דיי פארטי היו חמישה צעירים ממלבורן שבאוסטרליה, שעברו ללונדון ב־1980, ומשם לברלין, ונודעו כאחת הלהקות הפרועות והמפחידות בעולם. בחזית עמד ניק קייב, זמר רזה וגבוה שצרח, נהם וזחל על הבמה, ולצידו הגיטריסט רולנד ס. הווארד, הבסיסט טרייסי פיו ומיק הארווי, שניגן כמעט בכל כלי, גם בתופים. Junkyard, האלבום השני שלהם, יצא ב־1982.''',
'''זה רוק רועש ואפל, שעושה רושם של להקה שמתפרקת מול העיניים: בס כבד וחוזר, גיטרה שצורחת ומשתוללת, תופים כבדים וקייב, שמספר סיפורים מסויטים על רוצחים, מטיפים, חטאים ובובות שבורות. יש כאן בלוז ישן מהדרום האמריקאי, פאנק וסיפורי אימה, וכל זה מנוגן בכעס. Big-Jesus-Trash-Can הוא שיר מטורף על דת, חטא וצביעות, She's Hit מתאר רצח בצורה איטית ומאיימת, ו־Dead Joe הוא שיר מהיר ופרוע על תאונת דרכים. שיר הנושא חותם את האלבום ברעש גדול.''',
'''הלהקה התפרקה שנה אחר כך, אבל השפיעה מאוד על רוק הגותי ועל רוק הנויז. קייב והארווי המשיכו והקימו את Nick Cave and the Bad Seeds, יחד עם בליקסה ברגלד מאיינשטירצנדה נויבאוטן (אלבום 478). שם קייב הפך עם השנים לאחד מכותבי השירים החשובים בעולם, עם בלדות שקטות ויפות לצד הרעש. העטיפה, ציור פרוע של מפלצת במכונית מירוץ, נוצרה בידי אד רות׳, אמן אמריקאי מוכר של תרבות המכוניות.''',
'''זה אלבום רועש וקשה. אם אהבתם את Fire of Love של הגאן קלאב (אלבום 490), תמצאו כאן אותו בלוז אפל, רק פרוע וכאוטי עוד יותר. שמעו בעוצמה בינונית.''',
], [
('Big-Jesus-Trash-Can', 'שיר מטורף על דת, חטא וצביעות, עם בס כבד וצעקות של קייב.'),
("She's Hit", 'שיר איטי ומאיים על רצח, כמו בלוז מסרט אימה.'),
('Dead Joe', 'שיר מהיר ופרוע על תאונת דרכים, מלא רעש וכאוס.'),
])

add(510, [
'''ונום היו שלישייה מניוקאסל שבצפון אנגליה, שרצתה להיות הלהקה הכי כבדה, מהירה ומפחידה בעולם. הם קראו לעצמם בשמות במה מאיימים: קרונוס בבס ובשירה, מנטאס בגיטרה ואבאדון בתופים, והשתמשו בדימויים של השטן ושל שחור לבן מכל הכיוונים. Black Metal, האלבום השני שלהם, הוקלט מהר ובתקציב קטן, ויצא ב־1982.''',
'''הצליל גולמי ומלוכלך: גיטרה רועשת ומעוותת, תופים מהירים ולא תמיד מדויקים, וקרונוס שצועק ונוהם בקול צרוד. זה מרגיש יותר כמו מוטורהד (אלבום 463) שהשתגעו מאשר כמו להקות מטאל מלוטשות. שיר הנושא, שפותח את האלבום, הוא הצהרה על הסגנון כולו, ו־Countess Bathory מספר על רוזנת הונגרית מהמאה ה־16 שנאמר עליה שרצחה צעירות רבות. Teacher's Pet הוא שיר משעשע וגס על בית הספר, ו־Buried Alive איטי ומאיים, על אדם שנקבר בעודו חי. האווירה כולה תיאטרלית ומוגזמת, כמעט כמו סרט אימה זול, ויש בה גם הרבה הומור.''',
'''השם Black Metal הפך לשם של סגנון מוזיקה שלם, שהתפתח בעיקר בנורווגיה בשנות התשעים. ונום השפיעו גם על להקות הת׳ראש מטאל האמריקאיות של שנות השמונים, כמו מטאליקה וסלייר, שלמדו מהם מהירות ועוצמה. רבים אומרים שהם לא ניגנו טוב במיוחד, אבל האנרגיה שלהם פתחה דלת. גם העטיפה, עם ראש שטני בעל קרניים, נועדה בעיקר להבהיל הורים.''',
'''אל תיקחו את זה ברצינות רבה מדי, הלהקה עצמה לא לקחה. שמעו את שיר הנושא ואחר כך את Countess Bathory, ותשמעו מאיפה התחילו להקות מטאל רבות.''',
], [
('Black Metal', 'הצהרה על הסגנון כולו, שהעניקה לו את שמו, מהירה ורועשת.'),
('Countess Bathory', 'סיפור על רוזנת הונגרית אכזרית, עם ריף מאיים וצעקות.'),
("Teacher's Pet", 'שיר משעשע וגס על בית הספר, בקצב של רוקנרול מהיר.'),
])

add(511, [
'''בתחילת 1982 ישב ברוס ספרינגסטין (אלבומים 335 ו־409) בחדר השינה בביתו שבניו ג׳רזי, עם גיטרה אקוסטית, מפוחית ומכשיר הקלטה ביתי קטן של ארבעה ערוצים. הוא הקליט שירים חדשים כגרסאות ניסיון, כדי ללמד אותם אחר כך את להקתו. אבל כשהלהקה ניסתה לנגן אותם, משהו אבד. ספרינגסטין החליט להוציא את ההקלטות הביתיות כמו שהן, ו־Nebraska יצא באותה שנה, כמעט בלי סינגלים ובלי סיבוב הופעות.''',
'''הצליל פשוט ושקט: גיטרה, מפוחית, לפעמים מנדולינה או עוגב, וקולו של ספרינגסטין, נמוך ועייף, כמעט לוחש. השירים הם סיפורים קשים על אמריקה של אנשים שנשארו מאחור: פושעים, מובטלים, שוטרים ובני משפחה. שיר הנושא, הפותח, מסופר מפי צעיר שביצע סדרת רציחות בשנות החמישים, בלי חרטה. Atlantic City מספר על זוג שבורח לעיר ההימורים, כשהבחור מוכן לעבוד אצל הפשע המאורגן. Highway Patrolman מתאר שוטר שאחיו הוא פושע, ובלילה אחד עליו להחליט מה לעשות. Mansion on the Hill ו־My Father's House הם זיכרונות ילדות עצובים, ו־Reason to Believe חותם בשאלה איך אנשים ממשיכים להאמין.''',
'''Nebraska הפתיע את כולם, והפך לאחד האלבומים האהובים של ספרינגסטין, ולהשראה לאמנים רבים שהקליטו בבית. מאותן הקלטות יצאו גם שירים שהפכו לאלבום הבא שלו, Born in the U.S.A. (אלבום 546).''',
'''שמעו אותו בלילה, בשקט, כמו סיפורים קצרים. אחר כך השוו ל־Born to Run (אלבום 335), ותשמעו איך אותו אדם עובר מחלומות גדולים לשקט עצוב.''',
], [
('Atlantic City', 'זוג בורח לעיר ההימורים, והבחור מוכן לעבוד אצל הפשע המאורגן.'),
('Highway Patrolman', 'שוטר שאחיו פושע, ולילה אחד שבו עליו להחליט מה לעשות.'),
('Nebraska', 'סיפור רציחות מפי הרוצח עצמו, בקול שקט ובלי חרטה.'),
])

add(512, [
'''אסושייטס היו צמד מדנדי שבסקוטלנד: בילי מקנזי, זמר בעל קול יוצא דופן שיכול לעלות לגבהים של זמר אופרה ולרדת לנהמה עמוקה, ואלן ריינקין, נגן מוכשר שניגן כמעט בכל הכלים. ב־Sulk, שיצא ב־1982, הם נתנו לדמיון שלהם לרוץ חופשי, והאלבום נכנס לעשירייה הראשונה במצעד הבריטי.''',
'''המוזיקה צפופה, מוגזמת ומרגשת: סינתיסייזרים, גיטרות מעובדות, תופים חזקים, פסנתרים ועוד שכבות על שכבות, כאילו כל שיר הוא ארמון מלא חדרים. מעל הכל קולו של מקנזי, שעובר מלחישה לצרחה, משמחה לעצב, בלי מאמץ. Party Fears Two, הלהיט הגדול, הוא שיר פופ עליז עם פסנתר מתנגן ומילים מוזרות על מסיבה שהולכת ומתפרקת. Club Country מתאר בלעג מועדון לילה מלא באנשים מעושים, בקצב ריקוד מהיר. Skipping רך ומרחף, ויש באלבום גם רגעים אפלים, איטיים ומבלבלים, כמו גרסה מצמררת לשיר הישן Gloomy Sunday.''',
'''אסושייטס היו בדרך להצלחה גדולה, אבל מקנזי סירב לצאת לסיבוב הופעות גדול, וריינקין עזב זמן קצר אחר כך. מקנזי המשיך להקליט בשם הלהקה, אבל ההצלחה לא חזרה. הוא מת ב־1997, ועם השנים הוכר כאחד הקולות הגדולים והמיוחדים של הפופ הבריטי. Sulk נחשב לאחד האלבומים המקוריים והנועזים של התקופה, וזמרים רבים, מבריטניה ומחוצה לה, סיפרו כמה הושפעו מהקול ומהחופש של מקנזי.''',
'''שמעו את Party Fears Two, ושימו לב לקולו של מקנזי: כמה גבוה הוא עולה, ובאיזו קלות. ואם אתם אוהבים את רוקסי מיוזיק (אלבום 264), תמצאו כאן קרובים רחוקים.''',
], [
('Party Fears Two', 'הלהיט הגדול, שיר פופ עליז עם פסנתר מתנגן ומילים מוזרות.'),
('Club Country', 'לעג למועדון לילה מלא אנשים מעושים, בקצב ריקוד מהיר וסוחף.'),
('Skipping', 'שיר רך ומרחף, עם הקול הגבוה והמרגש של מקנזי.'),
])

add(513, [
'''אחרי שני אלבומים עם הזמר פול די׳אנו (הראשון הוא אלבום 469), איירון מיידן החליפו אותו בברוס דיקינסון, זמר עם קול חזק ותיאטרלי שיכול לעלות לגבהים עצומים. The Number of the Beast, האלבום הראשון איתו, יצא ב־1982 והגיע למקום הראשון במצעד הבריטי. מכאן הלהקה הפכה לאחת מלהקות המטאל הגדולות בעולם.''',
'''הבס הדוהר של סטיב האריס, שתי הגיטרות המנגנות יחד מנגינות כפולות, והקול של דיקינסון, שנשמע כמו מנהיג על במה ענקית, הם הבסיס. השירים מספרים סיפורים, כמעט כמו סרטים או ספרים. Run to the Hills מתאר את רדיפת האינדיאנים בידי המתיישבים באמריקה, מכמה נקודות מבט, בקצב של דהירת סוסים. שיר הנושא נפתח בציטוט מתוך "ספר ההתגלות" בתנ״ך הנוצרי, ומתאר חלום בלהות על טקס שטני, עם צרחה מפורסמת של דיקינסון. Hallowed Be Thy Name, שחותם, הוא סיפור של אסיר שממתין להוצאה להורג, ונחשב לאחד משירי המטאל הגדולים.''',
'''באמריקה כמה קבוצות דתיות האשימו את הלהקה בעבודת השטן ואף שרפו את התקליטים, מה שרק הוסיף לה פרסום. בפועל, השירים הם סיפורי אימה והיסטוריה, לא דרשות. האלבום הפך לאחד מאבני היסוד של המטאל, והשפיע על אינספור להקות. העטיפה, שבה הקמע אדי מפעיל את השטן כמו בובה על חוטים, היא אחת המוכרות בתולדות הרוק.''',
'''השוו את Running Free מהאלבום הראשון (469) ל־Run to the Hills כאן, ותשמעו מה עשה הזמר החדש. ואת Hallowed Be Thy Name כדאי לשמוע עד הסוף.''',
], [
('Run to the Hills', 'רדיפת האינדיאנים באמריקה, בקצב של דהירת סוסים ופזמון סוחף.'),
('The Number of the Beast', 'חלום בלהות על טקס שטני, עם צרחה מפורסמת של דיקינסון.'),
('Hallowed Be Thy Name', 'אסיר שממתין להוצאה להורג, אחד משירי המטאל הגדולים בכל הזמנים.'),
])

add(514, [
'''דוראן דוראן באו מבירמינגהם, וקראו לעצמם על שם דמות מסרט מדע בדיוני. הם היו חלק מגל "הרומנטיקנים החדשים", להקות שאהבו בגדים יפים, איפור וסינתיסייזרים, אבל ניגנו גם בגיטרה, בבס ובתופים כמו להקת רוק. Rio, האלבום השני שלהם, יצא ב־1982 והפך אותם לכוכבים עולמיים. העטיפה, ציור של אישה מחייכת בסגנון של מגזין אופנה, הפכה גם היא לסמל של התקופה.''',
'''המוזיקה היא פופ ריקודי חם ומבריק: בס פאנקי ומקפץ של ג׳ון טיילור, סינתיסייזרים של ניק רודס, גיטרה חדה של אנדי טיילור ותופים של רוג׳ר טיילור, שלושה שאינם קרובי משפחה, וקולו המלא של סיימון לה בון. Hungry Like the Wolf, עם הקליפ שצולם בג׳ונגל של סרי לנקה, הוא שיר ציד רומנטי ונמרץ. שיר הנושא, שנפתח בצלילי פסנתר מהופכים, הוא שיר אהבה עליז לבחורה דמיונית, עם קליפ על יאכטה בים הקריבי. Save a Prayer היא בלדה איטית ונוגה על אהבה של לילה אחד, ו־The Chauffeur, שחותם, אפל ומסתורי.''',
'''דוראן דוראן היו מהלהקות הראשונות שהבינו את כוחו של ערוץ MTV. הקליפים שלהם, שצולמו במקומות אקזוטיים כמו סרטים קצרים, הפכו אותם לכוכבים באמריקה, וגרמו להמוני מעריצות לצרוח בכל הופעה. מעבר לתדמית, Rio הוא אלבום פופ מצוין, עם נגינה מוקפדת ושירים שנשארים בראש.''',
'''שמעו את שיר הנושא, ושימו לב לבס של ג׳ון טיילור, שכמעט מוביל את השיר. אחר כך האזינו ל־Dare של היומן ליג (אלבום 489) מאותה תקופה, והשוו.''',
], [
('Hungry Like the Wolf', 'שיר ציד רומנטי ונמרץ, עם קליפ שצולם בג׳ונגל של סרי לנקה.'),
('Rio', 'שיר אהבה עליז לבחורה דמיונית, עם בס פאנקי ומקפץ.'),
('Save a Prayer', 'בלדה איטית ונוגה על אהבה של לילה אחד, עם סינתיסייזר חלומי.'),
])

add(515, [
'''הווילנט פמס היו שלושה צעירים ממילווקי, שניגנו ברחוב בכלים אקוסטיים: גורדון גאנו, ששר וניגן בגיטרה, בריאן ריצ׳י בגיטרה בס אקוסטית, וויקטור דלורנצו, שניגן על תוף סנר וכלים מאולתרים. יום אחד, כשניגנו מחוץ להופעה של הפרטנדרס (אלבום 477), שמע אותם הגיטריסט ג׳יימס הוניימן־סקוט, והזמין אותם לנגן באותו ערב לפני הלהקה. האלבום הראשון שלהם יצא ב־1983.''',
'''זה פאנק אקוסטי: שקט ורועש, מצחיק ועצוב, עם מעט מאוד כלים. גאנו, שכתב חלק מהשירים כשהיה עוד נער, שר בקול מתוח ועצבני על כל מה שמטריד נער מתבגר: אהבה, תסכול, בדידות ומבוכה. Blister in the Sun, הפותח, עם הפתיחה המפורסמת של הגיטרה והתוף, הפך להמנון של דורות של סטודנטים. Kiss Off הוא רשימה זועמת של תלונות, עם ספירה מצחיקה בפזמון. Add It Up מתחיל בשקט ונגמר בצעקות של תסכול, ו־Gone Daddy Gone מוסיף קסילופון שמח לשיר על פרידה.''',
'''האלבום לא הגיע למצעדים כשיצא, אבל עבר מיד ליד במשך שנים, ובסוף נמכר במיליוני עותקים, בלי להיט אחד גדול. הוא הפך לאחד מאלבומי הבכורה האהובים של הרוק האמריקאי העצמאי, ולפסקול קבוע של מסיבות סטודנטים. גאנו, בנו של כומר, כתב בהמשך גם שירים דתיים, והלהקה המשיכה להופיע עשרות שנים. הקול העצבני של גאנו והבס האקוסטי של ריצ׳י נשמעים כמו ויכוח בין שני חברים ברחוב.''',
'''שמעו את Blister in the Sun ואת Add It Up, ושימו לב כמה מעט כלים יש, וכמה אנרגיה. זה אלבום שהוכיח שפאנק לא צריך מגברים.''',
], [
('Blister in the Sun', 'הפתיחה המפורסמת של גיטרה ותוף, המנון של דורות של סטודנטים.'),
('Add It Up', 'מתחיל בשקט, מאיץ ומאיץ, ונגמר בצעקות של תסכול נערי.'),
('Kiss Off', 'רשימה זועמת של תלונות, עם ספירה מצחיקה ועצבנית בפזמון.'),
])

add(516, [
'''מלקולם מקלארן היה המנהל של הסקס פיסטולס (אלבום 394), איש של רעיונות פרובוקטיביים ושל אופנה. בתחילת שנות השמונים הוא החליט להקליט אלבום משלו, אף שכמעט לא ידע לשיר, והסתובב בעולם כדי לאסוף מוזיקה: מדרום אפריקה, מקובה, מהרי אמריקה ומרחובות ניו יורק. Duck Rock, שיצא ב־1983, הופק בידי טרבור הורן, שהפיק גם את ABC.''',
'''התוצאה היא אוסף מוזר ומשעשע: שירה וגיטרות מדרום אפריקה, קריאות של ריקודי כפר אמריקאיים, תופים קובניים והיפ הופ ניו יורקי, הכל מחובר בידי מקלארן, שמדבר ומכריז מעל כמו מנחה של תוכנית רדיו. Buffalo Gals, שיר ההיפ הופ, היה מהשירים הראשונים מחוץ לאמריקה שהביאו לקהל רחב את הסקרץ׳, השפשוף של התקליטים, בעזרת דיג׳יי מניו יורק. Double Dutch מתאר בנות שקופצות בחבל בשכונות ניו יורק, על מוזיקה דרום אפריקאית שמחה, והגיע לעשירייה הראשונה בבריטניה. בין השירים יש קטעי רדיו קצרים, כאילו מישהו מחליף תחנות.''',
'''האלבום היה שנוי במחלוקת: חלק מהמוזיקה הדרום אפריקאית נלקחה ממוזיקאים מקומיים שלא קיבלו קרדיט מלא, ומקלארן נתבע. ועדיין, הוא הביא לאנגליה את ההיפ הופ ואת מוזיקת סווטו, שנים לפני שהפכו למוכרות, והשפיע על אמנים רבים שחיברו בין מוזיקה מערבית למוזיקה מאפריקה. גם הקליפים, עם רקדני ברייקדאנס וגרפיטי, הביאו לטלוויזיה הבריטית את תרבות הרחוב של ניו יורק.''',
'''שמעו את Buffalo Gals, ואחריו את The Message של גרנדמאסטר פלאש (אלבום 498), ותשמעו איך ההיפ הופ נשמע כשהגיע לאנגליה.''',
], [
('Double Dutch', 'בנות קופצות בחבל בניו יורק, על מוזיקה דרום אפריקאית שמחה.'),
('Buffalo Gals', 'היפ הופ ניו יורקי עם סקרץ׳, שהגיע לקהל רחב באנגליה.'),
('Duck for the Oyster', 'קריאות של ריקוד כפרי אמריקאי, בגרסה מוזרה, מהירה ומצחיקה.'),
])

add(517, [
'''דף לפרד באו משפילד, והיו חלק מהגל החדש של המטאל הבריטי, לצד איירון מיידן (אלבום 469). אבל הם רצו משהו אחר: רוק כבד שאפשר לשיר איתו ברדיו, עם פזמונים גדולים. לשם כך הם עבדו עם המפיק מאט לאנג, שהפיק את Back in Black של AC/DC (אלבום 456), ושעבד איתם שעות ארוכות על כל צליל. Pyromania יצא בתחילת 1983 והגיע למקום השני במצעד האמריקאי, ורק Thriller (אלבום 508) הקדים אותו.''',
'''הצליל מבריק ועוצמתי: גיטרות כבדות אבל נקיות, תופים גדולים, ובעיקר קולות רקע מרובים, שכבות על שכבות של מקהלה, שהפכו כל פזמון להמנון של אצטדיון. ג׳ו אליוט שר בקול צרוד ונלהב. Photograph, הלהיט הגדול, הוא שיר אהבה של מעריץ לכוכבת שהוא מכיר רק מתמונה. Rock of Ages נפתח בקריאה מוזרה בשפה מומצאת, שאמר המפיק לאנג עצמו, ומתפתח להמנון שכולו קריאות קהל. Foolin' מתחיל בשקט ובקול רך ומתפוצץ בפזמון, ו־Too Late for Love איטי ודרמטי.''',
'''Pyromania נמכר במיליוני עותקים, והפך לתבנית לרוק הכבד הפופולרי של שנות השמונים, שבו פזמון קליט חשוב לא פחות מריף כבד. במהלך ההקלטות הגיטריסט פיט וויליס פוטר, ופיל קולן נכנס במקומו. בסוף השנה שאחרי איבד המתופף ריק אלן את ידו בתאונת דרכים, והלהקה חיכתה לו עד שלמד לנגן מחדש, בעזרת תופים מיוחדים.''',
'''שמעו את Photograph, ושימו לב לקולות הרקע: כמה שכבות של שירה יש שם. אחר כך שמעו את Back in Black (אלבום 456), ותשמעו את אותו מפיק עם להקה אחרת.''',
], [
('Photograph', 'מעריץ מאוהב בכוכבת שהוא מכיר רק מתמונה, עם פזמון של אצטדיון.'),
('Rock of Ages', 'פתיחה בשפה מומצאת, ואחריה המנון רוק מלא קריאות קהל.'),
("Foolin'", 'מתחיל בשקט ובקול רך, ואז מתפוצץ בפזמון גדול וסוחף.'),
])

add(518, [
'''R.E.M. באו מאתנס, עיירת אוניברסיטה בג׳ורג׳יה, ארבעה חברים שניגנו במסיבות ובמועדונים קטנים בדרום אמריקה. הזמר מייקל סטייפ שר בקול רך ועמום, כמעט ממלמל, כך שקשה להבין את המילים. הגיטריסט פיטר באק ניגן בגיטרה מצלצלת שהזכירה את הבירדס (אלבום 57), והבסיסט מייק מילס הוסיף הרמוניות יפות. Murmur, האלבום הראשון שלהם, יצא ב־1983, ומגזין רולינג סטון בחר בו כאלבום השנה, לפני Thriller.''',
'''השם Murmur, "מלמול", מתאים לו: המילים של סטייפ חצי מובנות, כמו חלום, והמוזיקה מסתורית וחמה. הגיטרות מצלצלות, הבס מלודי ושמח, ויש פסנתר, גיטרות אקוסטיות וצלילים של הדרום האמריקאי, עם אווירה של יער לח ובית ישן. Radio Free Europe, הפותח, הוא שיר מהיר וקליט שאיש לא באמת יודע על מה הוא. Talk About the Passion הוא בלדה נוגה ויפה, עם צ׳לו. Perfect Circle, שיר שקט עם פסנתר, נכתב בהשראת ילדים שמשחקים בערב, ו־Catapult ו־Laughing קצביים וחלומיים.''',
'''Murmur פתח את הדרך לרוק של מכללות, להקות עצמאיות שנוסעות מעיר לעיר ומנגנות לסטודנטים, ומשם לרוק האלטרנטיבי של שנות התשעים. R.E.M. הפכו בהמשך לאחת הלהקות הגדולות בעולם, עם Losing My Religion ושירים רבים אחרים, אבל רבים עדיין אוהבים את ההתחלה המסתורית הזאת, ורואים בה את האלבום הטוב ביותר שלהם. גם העטיפה, תמונה של צמחי קודזו מטפסים שמכסים את הדרום האמריקאי, מתאימה לאווירה.''',
'''אל תנסו להבין את המילים, פשוט תקשיבו לצליל. אם אהבתם את Underwater Moonlight של הסופט בויז (אלבום 460), תשמעו כאן קרובים אמריקאים.''',
], [
('Radio Free Europe', 'פתיחה מהירה וקליטה, שאיש לא באמת יודע על מה היא מדברת.'),
('Talk About the Passion', 'בלדה נוגה ויפה על תשוקה ואמונה, עם צ׳לו וגיטרות מצלצלות.'),
('Perfect Circle', 'שיר שקט ויפה עם פסנתר, בהשראת ילדים שמשחקים בשעת ערב.'),
])

add(519, [
'''The The הם בעצם אדם אחד: מאט ג׳ונסון, מוזיקאי לונדוני שכתב, שר והפיק כמעט הכל בעצמו, ונעזר בנגנים אורחים שונים בכל אלבום. Soul Mining, האלבום הראשון בשם הזה, יצא ב־1983, כשג׳ונסון היה בן עשרים ושתיים בלבד. הוא כתב בו על בדידות, על תסכול ועל הקושי להתבגר בלונדון של שנות השמונים.''',
'''המוזיקה היא פופ אלקטרוני עם לב: סינתיסייזרים, תופים, אקורדיון, פסנתר וכלי הקשה מכל העולם, וקולו העייף והכן של ג׳ונסון. This Is the Day, הפותח, הוא שיר על יום שבו החיים אמורים להשתנות, עם אקורדיון שמח וקצב מתנדנד, שמח ועצוב בבת אחת. Uncertain Smile מסתיים בסולו פסנתר ארוך וסוער של ג׳ולס הולנד, שהפך לאחד הרגעים המפורסמים באלבום. Giant הוא קטע ארוך של כעשר דקות, עם תופים שבטיים וקריאות חוזרות, ו־The Sinking Feeling מהיר ועצבני, על תחושה של שקיעה. בתופים מנגן גם זיקה מאניקה מאורנג׳ ג׳וס (אלבום 507).''',
'''Soul Mining לא היה להיט ענק, אבל הוא נחשב לאחד מאלבומי הפופ האישיים והחכמים של שנות השמונים. This Is the Day הפך עם השנים לשיר אהוב, שמופיע בסרטים ובפרסומות, וג׳ונסון המשיך להקליט אלבומים פוליטיים ואישיים במשך עשרות שנים. ג׳ונסון ניגן ושר את רוב החלקים בעצמו, וכתב על דברים שאחרים מתביישים להודות בהם.''',
'''שמעו את Uncertain Smile עד הסוף, בשביל סולו הפסנתר. ואם אהבתם את Penthouse and Pavement של Heaven 17 (אלבום 480), תמצאו כאן צד רך ואישי יותר של אותה תקופה.''',
], [
('This Is the Day', 'יום שבו החיים אמורים להשתנות, עם אקורדיון שמח ועצוב בבת אחת.'),
('Uncertain Smile', 'שיר פופ נוגה שמסתיים בסולו פסנתר ארוך וסוער של ג׳ולס הולנד.'),
('Giant', 'קטע ארוך של כעשר דקות, עם תופים שבטיים וקריאות חוזרות.'),
])

add(520, [
'''אחרי Heartattack and Vine (אלבום 472), טום ווייטס עזב את חברת התקליטים הוותיקה שלו, שלא הבינה את הכיוון החדש. בהשפעת אשתו, קתלין ברנן, שהכירה לו מוזיקה מוזרה ממקומות רבים, ובהשראת קפטן ביפהארט (אלבום 137), הוא החליט לזנוח את הפסנתר והכינורות ולבנות עולם צלילים חדש. Swordfishtrombones, שהפיק בעצמו, יצא ב־1983.''',
'''הצליל נשמע כמו תזמורת של גרוטאות: מרימבה, עוגב משאבות ישן, חלילית סקוטית, תופים של פחי מתכת, קונטרבס, חצוצרה צרודה, וגיטרות לא מכוונות. ווייטס שר, נובח, מתלחש ומספר סיפורים, בקול שנשמע יותר צרוד מתמיד. Underground, הפותח, מתאר עולם תחתון של אנשים שחיים מתחת לאדמה, בקצב צועד ומוזר. Johnsburg, Illinois הוא שיר אהבה קצרצר ויפה לברנן, על העיירה שבה גדלה. In the Neighborhood נשמע כמו תזמורת מכבי אש בתהלוכה, ומתאר שכונה רגילה ברחמים. Frank's Wild Years הוא סיפור מדובר ומצחיק־מצמרר על אדם רגיל שמצית את ביתו ונוסע.''',
'''Swordfishtrombones היה תחילתו של ווייטס החדש, שהמשיך עם Rain Dogs ואלבומים רבים אחרים, והפך לאחד האמנים המקוריים ביותר במוזיקה האמריקאית. מוזיקאים רבים, מכל הסגנונות, למדו ממנו שאפשר לעשות מוזיקה גם מחפצים שבורים, ושקול לא יפה יכול להיות יפה מאוד. ווייטס עצמו הפך גם לשחקן קולנוע, ולעיתים קרובות שיחק דמויות מוזרות כמו בשיריו.''',
'''שמעו את Heartattack and Vine (אלבום 472) ומיד אחריו את האלבום הזה. שלוש שנים בלבד ביניהם, ונדמה שאלה שני אנשים שונים לגמרי.''',
], [
('In the Neighborhood', 'תזמורת של תהלוכה צועדת ושיר רחום על שכונה רגילה.'),
('Johnsburg, Illinois', 'שיר אהבה קצרצר ויפה לאשתו, על העיירה שבה גדלה.'),
('Underground', 'עולם תחתון של אנשים שחיים מתחת לאדמה, בקצב צועד ומוזר.'),
])

add(521, [
'''הבלו נייל היו שלישייה מגלזגו: פול ביוקנן, ששר בקול רך ושבור, רוברט בל ופול ג׳וזף מור. את האלבום הראשון שלהם הם הקליטו לאט ובקפדנות, והוציאה אותו חברה שעד אז ייצרה רק מערכות שמע יוקרתיות, Linn, שהקימה חברת תקליטים במיוחד בשבילם, אחרי ששמעה את ההקלטות. A Walk Across the Rooftops יצא ב־1984, עם שבעה שירים בלבד.''',
'''המוזיקה שקטה, איטית ומלאת אוויר: סינתיסייזרים רכים, תופים עדינים, פסנתר, כלי מיתר ובס עמוק, עם הרבה מקום ריק בין הצלילים. ביוקנן שר על לילות בעיר, על אהבה, על גשם ועל אורות של מכוניות, כמו בסרט שחור לבן ישן. Tinseltown in the Rain הוא שיר שמח ונוגה על עיר מנצנצת בגשם, עם כלי מיתר קופצניים. שיר הנושא, הפותח, הוא הליכה לילית על הגגות, ו־Stay מתחנן בפשטות לאהובה שתישאר. Easter Parade שקט במיוחד, כמעט רק פסנתר וקול, ומתאר תהלוכה ברחוב ביום חג.''',
'''האלבום לא הפך ללהיט, אבל קהל קטן ונאמן התאהב בו, והוא נחשב לאחד האלבומים היפים והאינטימיים של שנות השמונים. הבלו נייל עבדו לאט מאוד, והאלבום הבא שלהם יצא רק חמש שנים אחר כך. מוזיקאים רבים ראו בהם השראה, והם נחשבים לסוד שמור של המוזיקה הבריטית. ביוקנן המשיך לשיר בקול שבור ורך גם עשרות שנים אחר כך, באלבומי סולו שקטים.''',
'''זה אלבום ללילה, לנסיעה בגשם או לחלון פתוח. שמעו אותו ברצף ובשקט, ושימו לב כמה מעט צלילים יש, וכמה רגש.''',
], [
('Tinseltown in the Rain', 'עיר מנצנצת בגשם, שמח ונוגה, עם כלי מיתר קופצניים.'),
('Stay', 'בקשה פשוטה ומרגשת מהאהובה שתישאר, בקול רך ושבור ובקצב עדין.'),
('Easter Parade', 'כמעט רק פסנתר וקול, ותהלוכה שקטה ברחוב ביום חג.'),
])

add(522, [
'''האנוי רוקס באו מהלסינקי שבפינלנד, מקום שאיש לא ציפה ממנו לרוקנרול זוהר. הם נראו כמו כוכבים: שיער מנופח, איפור, צעיפים ותכשיטים, כמו הניו יורק דולס ורולינג סטונס בגרסה פרועה. הזמר מייקל מונרו, שגם ניגן בסקסופון ובמפוחית, והגיטריסט אנדי מקוי היו לב הלהקה. Back to Mystery City, אלבום האולפן השלישי שלהם, הוקלט בלונדון ויצא ב־1983.''',
'''המוזיקה היא רוקנרול מהיר ושמח, עם גיטרות חדות, פזמונים קליטים, סקסופון ומפוחית, ומעליהם הקול הצעיר והנלהב של מונרו. יש בה פאנק, גלאם של שנות השבעים ופופ של שנות השישים, והכל מנוגן באנרגיה של להקה שחיה על הכביש. Malibu Beach Nightmare הוא שיר מהיר ומצחיק על חוף ים ובנות, Until I Get You הוא בלדה רומנטית וכואבת, ו־Mental Beat ו־Tooting Bec Wreck מקפצים ופרועים. שיר הנושא, שחותם, הוא המנון לעיר מסתורית דמיונית.''',
'''האנוי רוקס היו בדרך להצלחה באמריקה, אבל בסוף 1984 נהרג המתופף רזל בתאונת דרכים בלוס אנג׳לס, כשנהג ברכב זמר של להקה אחרת, שיכור. הלהקה התפרקה זמן קצר אחר כך. עם השנים התברר כמה היא השפיעה: גאנז אנד רוזס ולהקות רבות של רוק זוהר בשנות השמונים למדו ממנה את המראה ואת הצליל, ואקסל רוז עצמו דיבר עליה בהערכה רבה.''',
'''אם אתם אוהבים רוקנרול פשוט, מהיר ושמח, התחילו ב־Malibu Beach Nightmare. ואם אהבתם את Raw Power של הסטוג׳ס (אלבום 298), תשמעו כאן את הצד הזוהר והשמח של אותה אנרגיה.''',
], [
('Malibu Beach Nightmare', 'שיר מהיר ומצחיק על חוף ים ובנות, עם סקסופון.'),
('Until I Get You', 'בלדה רומנטית וכואבת, עם הקול הצעיר והנלהב של מונרו.'),
('Back to Mystery City', 'שיר הנושא, המנון לעיר מסתורית דמיונית, שחותם את האלבום.'),
])

add(523, [
'''סינדי לאופר גדלה בקווינס שבניו יורק, עזבה את הבית בגיל צעיר, עבדה בעבודות מזדמנות ושרה בלהקות קטנות. כשהגיעה לאלבום הבכורה שלה, She's So Unusual, ב־1983, היא כבר הייתה בת שלושים, עם שיער צבוע בכתום ובוורוד, בגדים צבעוניים מחנויות יד שנייה, וקול שיכול לעבור מצפצוף ילדותי לצעקה עוצמתית.''',
'''האלבום עליז, צבעוני ומלא חיים: סינתיסייזרים, גיטרות ופופ קליט, וקולה המיוחד של לאופר, שתמיד נשמע כאילו היא צוחקת. Girls Just Want to Have Fun, שיר שנכתב במקור בידי גבר, הפך אצלה להמנון של נשים צעירות שרוצות פשוט ליהנות, כמו כל אחד אחר, עם קליפ שבו מופיעה גם אמה. Time After Time היא בלדה שקטה ויפה על אהבה שתמיד תחכה, ששרו אחר כך מאות אמנים. She Bop הוא שיר מחוצף ומצחיק על הנאה עצמית, שעורר שערורייה בקרב שומרי המוסר באמריקה. All Through the Night רך ומרחף, ויש גם גרסה לשיר מוקדם של פרינס (אלבום 497), When You Were Mine.''',
'''לאופר הייתה הזמרת הראשונה שארבעה שירים מאלבום הבכורה שלה הגיעו לחמשת המקומות הראשונים במצעד האמריקאי, והיא זכתה בפרס הגראמי לאמנית החדשה. בשנים שאחר כך היא נודעה גם כפעילה למען זכויות להט״ב, וכתבה את המוזיקה למחזמר מצליח בברודוויי.''',
'''כולם מכירים את Girls Just Want to Have Fun, אז נסו את Time After Time בשקט, ושימו לב כמה רגש יש בקול שנשמע בשיר הקודם כל כך שובב.''',
], [
('Girls Just Want to Have Fun', 'המנון של נשים צעירות שרוצות פשוט ליהנות, עליז ומדבק.'),
('Time After Time', 'בלדה שקטה ויפה על אהבה שתמיד תחכה, ששרו אחר כך מאות אמנים.'),
('She Bop', 'שיר מחוצף ומצחיק על הנאה עצמית, שעורר שערורייה בקרב שומרי המוסר.'),
])

add(524, [
'''פול סיימון, חצי מסיימון וגרפונקל (אלבומים 71, 125 ו־197) ובעל קריירת סולו מצליחה (אלבום 263), התאחד עם ארט גרפונקל ב־1981 להופעה ענקית בסנטרל פארק. התוכנית הייתה להקליט אחריה אלבום משותף, אבל במהלך העבודה החליט סיימון להסיר את קולות חברו, והאלבום יצא ב־1983 בשמו בלבד. Hearts and Bones נכשל מסחרית, והפך לאחד האלבומים הפחות מוכרים שלו, אבל רבים רואים בו פנינה.''',
'''השירים אישיים וכנים, וחלקם עוסקים בנישואיו הסוערים לשחקנית קארי פישר. שיר הנושא מתאר זוג במסע בניו מקסיקו, ושואל מה מחזיק אהבה, "הלבבות והעצמות". Train in the Distance מספר על אהבה ראשונה ונישואים שנגמרו, ועל הרכבת הרחוקה שמסמלת את התקווה שתמיד נמשכת. René and Georgette Magritte with Their Dog After the War הוא שיר עדין וחלומי על הצייר הבלגי מגריט ואשתו, שמאזינים בסתר לשירי דו־וופ אמריקאיים. The Late Great Johnny Ace מחבר את מותו של זמר בשנות החמישים עם הרצח של ג׳ון לנון, ומסתיים בקטע של המלחין פיליפ גלאס. Allergies, הפותח, מצחיק ועצבני.''',
'''אחרי הכישלון, סיימון נסע לדרום אפריקה, ושלוש שנים אחר כך הוציא את Graceland, אחד האלבומים המצליחים בקריירה שלו. Hearts and Bones נשאר האלבום שבו הוא חשף את עצמו יותר מכל, ושיריו מוערכים היום יותר מאשר אז.''',
'''שמעו את Train in the Distance ואת שיר הנושא בשקט. ואם אתם מכירים את Paul Simon (אלבום 263), תשמעו כמה הוא התבגר, ונהיה פגיע יותר.''',
], [
('Hearts and Bones', 'זוג במסע בניו מקסיקו, ושאלה גדולה על מה מחזיק אהבה.'),
('Train in the Distance', 'אהבה ראשונה, נישואים שנגמרו, ורכבת רחוקה שמסמלת תקווה שלא נגמרת.'),
('René and Georgette Magritte with Their Dog After the War', 'שיר עדין וחלומי על הצייר מגריט ואשתו ושירי הדו־וופ שלהם.'),
])

add(525, [
'''אחרי Crocodiles (אלבום 462) ואלבום שני מוצלח, אקו והבאנימן נכנסו לאולפן לעבוד על השלישי, והעבודה לא הלכה. חברת התקליטים דחתה את הגרסה הראשונה, כי לא היו בה להיטים, והלהקה חזרה להקליט, הפעם בעזרת הכנר ההודי שנקר, שהוסיף כלי מיתר עם צליל מזרחי. Porcupine יצא בתחילת 1983 והגיע למקום השני במצעד הבריטי, ההצלחה הגדולה שלהם עד אז.''',
'''האלבום קר, חד ומתוח, כמו העטיפה שבה הלהקה עומדת על מפל קפוא באיסלנד. הגיטרות של וויל סרג׳נט קשות ומתפתלות, התופים חזקים, ומעליהם הקול הדרמטי של איאן מקולוך. The Cutter, הפותח, נפתח בכינור הודי מסתלסל ומתפתח לשיר רוק נרגש וזועם, והגיע לעשירייה הראשונה במצעד. The Back of Love מהיר ועצבני, כמעט מבוהל, ו־Heads Will Roll איטי ומאיים. שיר הנושא קודר וכבד, ו־In Bluer Skies, שחותם, נשמע כמו תקווה קטנה אחרי סערה.''',
'''Porcupine נחשב לאלבום הקשה והאפל של הלהקה, אבל הוא גם הוכיח שהיא יודעת לכתוב להיטים בלי לוותר על המוזרות שלה. שנה אחר כך הם הוציאו את Ocean Rain (אלבום 542), שבו הכינורות והתזמורת כבר הפכו לחלק מהצליל. רבים בלהקה עצמה זוכרים את ימי Porcupine כתקופה קשה של מתחים, ואפשר לשמוע את המתח הזה בכל שיר. בתופים מנגן פיט דה פרייטאס, שנחשב לאחד המתופפים המיוחדים של התקופה.''',
'''שמעו את The Cutter, ושימו לב לכינור ההודי בפתיחה. אחר כך השוו ל־Crocodiles (אלבום 462), ותשמעו כמה הלהקה גדלה בשלוש שנים.''',
], [
('The Cutter', 'פתיחה בכינור הודי מסתלסל, ואחריה שיר רוק נרגש וזועם.'),
('The Back of Love', 'שיר מהיר, עצבני וכמעט מבוהל, עם גיטרות מתפתלות ותופים דוהרים.'),
('In Bluer Skies', 'השיר החותם, איטי ויפה, כמו תקווה קטנה אחרי סערה.'),
])

add(526, [
'''זי זי טופ היו שלישייה מטקסס, שניגנה בלוז־רוק כבד ומלוכלך כבר משנות השבעים (אלבום 294). שניים מהם, הגיטריסט בילי גיבונס והבסיסט דאסטי היל, גידלו זקנים ארוכים במיוחד, והמתופף, שנקרא דווקא פרנק בירד, "זקן", היה היחיד בלי זקן. ב־Eliminator, שיצא ב־1983, הם הפתיעו את כולם והוסיפו לבלוז הטקסני שלהם סינתיסייזרים וקצב קבוע ומכני של שנות השמונים.''',
'''הצליל הוא בוגי טקסני ישן, עם ריפים פשוטים וגיטרה רועמת, אבל מתחתיו פועם קצב ריקוד אלקטרוני, יציב ומבריק. גיבונס שר בקול נמוך וצרוד, עם הרבה הומור. Gimme All Your Lovin', הפותח, הוא שיר מהיר וקליט על תשוקה. Sharp Dressed Man מסביר בחיוך שכל הבנות משתגעות אחרי גבר לבוש היטב. Legs, עם סינתיסייזר מקפץ, הוא שיר הערצה לרגליים של אישה, ו־TV Dinners מצחיק, על ארוחות קפואות מול הטלוויזיה.''',
'''הקליפים של האלבום, שבהם מופיעה מכונית פורד אדומה משנות השלושים בשם Eliminator, שלוש בחורות יפות והשלישייה עם הזקנים, הפכו לסמל של ערוץ MTV באותן שנים. האלבום נמכר בלמעלה מעשרה מיליון עותקים באמריקה, והפך להקה ותיקה של בלוז לכוכבי פופ. היו מעריצים ותיקים שהתלוננו על הצליל החדש, אבל רוב הקהל פשוט רקד, והזקנים הפכו לאחד הסמלים המוכרים של הרוק. באלבום הבא הם המשיכו באותה דרך, עם עוד יותר סינתיסייזרים.''',
'''שמעו את La Grange מ־Tres Hombres (אלבום 294), ואחריו את Sharp Dressed Man. אותה להקה, אותה גיטרה, עשר שנים ומכונה אחת ביניהם.''',
], [
('Sharp Dressed Man', 'כל הבנות משתגעות אחרי גבר לבוש היטב, בחיוך ובקצב בוגי.'),
("Gimme All Your Lovin'", 'פתיחה מהירה וקליטה על תשוקה, עם גיטרה רועמת וקצב מכני.'),
('Legs', 'שיר הערצה משעשע לרגליים של אישה, עם סינתיסייזר מקפץ.'),
])

add(527, [
'''אנני לנוקס ודייב סטיוארט היו זוג, וניגנו יחד בלהקה בשם The Tourists, שהתפרקה כשהקשר ביניהם נגמר. הם החליטו להמשיך לעבוד יחד כצמד, בשם יוריתמיקס, והקליטו את האלבום השני שלהם באולפן קטן שבנו בעליית גג בלונדון, עם ציוד זול. Sweet Dreams (Are Made of This) יצא בתחילת 1983 והפך אותם לכוכבים.''',
'''הצליל הוא סינת־פופ קר ומהפנט, עם מכונות תופים, סינתיסייזרים וקולה העמוק והחזק של לנוקס, שעובר מקור לחום בבת אחת. שיר הנושא, שנבנה על קו סינתיסייזר פשוט וחוזר, אומר שכל אחד מחפש משהו, ושיש מי שרוצה לנצל ומי שרוצה להיות מנוצל. הוא הגיע למקום הראשון במצעד האמריקאי. Love Is a Stranger מתאר אהבה כמו התמכרות מסוכנת, ו־This City Never Sleeps, שחותם, נשמע כמו לילה ארוך בעיר שלא נרדמת, עם רעשי רקע של עיר. יש גם גרסה מפתיעה לשיר הסול Wrap It Up של סם ודייב.''',
'''המראה של לנוקס, עם שיער קצר כתום וחליפה של גבר, הפך לאחד הסמלים של שנות השמונים, והקליפים של הצמד שודרו בלי הפסקה. יוריתמיקס המשיכו להצליח במשך עשור, ולנוקס הפכה לאחת הזמרות המוערכות בבריטניה, עם קריירת סולו מצליחה. לנוקס למדה קודם מוזיקה קלאסית באקדמיה בלונדון, ועזבה כדי לשיר פופ.''',
'''שמעו את שיר הנושא, ושימו לב כמה מעט יש בו: קו סינתיסייזר אחד, תופים וקול. ואם אהבתם את Non-Stop Erotic Cabaret של סופט סל (אלבום 483), זה צד אחר, קר וגאה יותר, של אותו צליל.''',
], [
('Sweet Dreams (Are Made of This)', 'קו סינתיסייזר מהפנט וקול עמוק, על מה שכולם מחפשים, מקום ראשון באמריקה.'),
('Love Is a Stranger', 'אהבה כמו התמכרות מסוכנת, קרה ומפתה, עם קול עוצמתי.'),
('This City Never Sleeps', 'לילה ארוך ומהפנט בעיר שלא נרדמת, עם רעשי רקע של עיר.'),
])

add(528, [
'''U2 באו מדבלין, ארבעה חברים מבית הספר שהקימו להקה בגיל צעיר מאוד, עוד לפני שידעו לנגן. ב־War, האלבום השלישי שלהם, שיצא בתחילת 1983 בהפקת סטיב לילִיווייט (שהפיק גם את אלבום 459), הם הפכו מלהקה מבטיחה ללהקה חשובה. זה היה האלבום הראשון שלהם שהגיע למקום הראשון במצעד הבריטי.''',
'''כמו שהשם אומר, האלבום עוסק במלחמה, באלימות ובשלום, והצליל מתאים: תופים צבאיים של לארי מאלן, גיטרה חדה ומהדהדת של דה אדג׳, בס יציב של אדם קליטון, וקולו הנלהב של בונו, שמתחנן וצועק. Sunday Bloody Sunday, הפותח, מתאר את היום שבו נורו מפגינים בצפון אירלנד ב־1972, ושואל כמה זמן עוד נצטרך לשיר את השיר הזה, עם כינור ותופים כמו צעדה. New Year's Day נכתב בהשראת התנועה הפולנית "סולידריות", עם פסנתר וגיטרה צלולים. Seconds עוסק בפחד מפצצה גרעינית, ו־40, שחותם, הוא מזמור מתוך ספר תהילים, שהלהקה נהגה לסיים בו הופעות כשהקהל ממשיך לשיר.''',
'''War הפך את U2 ללהקה גדולה באמריקה, בעיקר בזכות הופעה מצולמת באמפיתאטרון רד רוקס בקולורדו, בגשם ובערפל. בשנים הבאות הם הפכו לאחת הלהקות הגדולות בעולם, ושמרו על הרצינות ועל הרצון לדבר על העולם. גם העטיפה, פניו של ילד עם מבט חודר, אותו ילד שהופיע על עטיפת האלבום הראשון שלהם, הפכה למוכרת.''',
'''שמעו את Sunday Bloody Sunday, ושימו לב לתופים בפתיחה. אחר כך שמעו את 40 בסוף, ודמיינו אצטדיון שלם שממשיך לשיר אחרי שהלהקה ירדה מהבמה.''',
], [
('Sunday Bloody Sunday', 'יום שבו נורו מפגינים בצפון אירלנד, עם תופים כמו צעדה.'),
("New Year's Day", 'שיר על תקווה בזמנים קשים, עם פסנתר וגיטרה צלולים.'),
('40', 'מזמור מתוך ספר תהילים, שבו הלהקה נהגה לסיים הופעות.'),
])

add(529, [
'''הפוליס (אלבום 433) היו שלישייה: סטינג בבס ובשירה, אנדי סאמרס בגיטרה וסטיוארט קופלנד בתופים. עד 1983 הם היו אחת הלהקות הגדולות בעולם, אבל גם לא הסתדרו זה עם זה, והמתחים ביניהם היו קשים. Synchronicity, האלבום החמישי שלהם, הוקלט באי מונטסראט שבים הקריבי, כשכל אחד מהם מנגן בחדר נפרד. זה היה האלבום האחרון שלהם.''',
'''השם לקוח מרעיון של הפסיכולוג קרל יונג, על צירופי מקרים שיש להם משמעות. הצליל כבר רחוק מהרגאיי־פאנק המוקדם שלהם: יש בו מוזיקה אלקטרונית, ג׳אז, ומעט הקשה. Every Breath You Take, הלהיט הגדול, נשמע כמו שיר אהבה, אבל הוא בעצם שיר על קנאה ומעקב אובססיבי, "כל נשימה שתנשמי, אני אצפה בך". King of Pain הוא רשימה של דימויים לכאב, ו־Wrapped Around Your Finger איטי ומסתורי. Synchronicity II מתאר משפחה שמתפרקת בפרברים, ובמקביל מפלצת שעולה מאגם בסקוטלנד. Tea in the Sahara, שחותם, שקט ומרחף, בהשראת רומן על שלוש אחיות במדבר.''',
'''Synchronicity החליף את Thriller (אלבום 508) במקום הראשון במצעד האמריקאי, ונשאר שם שבועות רבים. מיד אחר כך הלהקה יצאה לסיבוב הופעות ענק, ולאחריו נפרדה. סטינג המשיך לקריירת סולו מצליחה, והשלישייה התאחדה רק לסיבוב הופעות ב־2007. Every Breath You Take הפך לאחד השירים המושמעים ביותר ברדיו בכל הזמנים, ולעיתים קרובות מנגנים אותו בחתונות, למרות המילים.''',
'''שמעו את Every Breath You Take, וקראו את המילים. אחר כך השוו ל־Reggatta de Blanc (אלבום 433), ותשמעו כמה הלהקה השתנתה בארבע שנים.''',
], [
('Every Breath You Take', 'נשמע כמו שיר אהבה, אבל הוא בעצם שיר על קנאה ומעקב.'),
('Wrapped Around Your Finger', 'שיר איטי ומסתורי על כוח ושליטה ביחסים, עם קצב רגאיי עדין.'),
('Synchronicity II', 'משפחה מתפרקת בפרברים, ומפלצת שעולה באותו רגע מאגם בסקוטלנד.'),
])

add(530, [
'''המיט פאפטס באו מפיניקס שבמדבר אריזונה: שני אחים, קרט קירקווד בגיטרה ובשירה וכריס קירקווד בבס, והמתופף דריק בוסטרום. הם התחילו כלהקת הארדקור מהירה ורועשת, והקליטו בחברת SST, החברה של בלאק פלאג (אלבום 486). אבל באלבום השני, Meat Puppets II, שיצא ב־1984, הם הפתיעו: פתאום יש קאנטרי, פסיכדליה ושירים איטיים ומוזרים.''',
'''המוזיקה נשמעת כמו נסיעה במדבר בחום של צהריים: גיטרות מתפתלות ומבריקות, בס שקופץ, תופים פשוטים, והקול של קרט, שלפעמים שר בצרידות ולפעמים כמעט מזייף בכוונה. יש כאן קאנטרי של בוקרים, רוק פסיכדלי של שנות השישים ופאנק, הכל ביחד. Plateau מתאר רמה מסתורית במדבר, שאין עליה כלום חוץ מדלי, סמרטוט וספר מאויר על ציפורים. Lake of Fire הוא שיר מצחיק־מפחיד על המקום שאליו הולכים אנשים רעים אחרי המוות. Oh, Me שקט וחלומי, ו־Split Myself in Two, הפותח, עדיין רועש ופאנקי.''',
'''האלבום לא הצליח בזמנו, אבל השפיע על להקות רבות של רוק אלטרנטיבי. ב־1993 נירוונה ביצעו שלושה משיריו, Plateau, Oh, Me ו־Lake of Fire, בהופעה האקוסטית המפורסמת שלהם בערוץ MTV, עם האחים קירקווד על הבמה. מאז רבים גילו את האלבום מחדש, והוא נחשב לאחד האלבומים המקוריים של הרוק האמריקאי העצמאי, זה שהראה שגם להקת פאנק יכולה לאהוב קאנטרי.''',
'''שמעו את Lake of Fire כאן, ואם אתם מכירים את הגרסה של נירוונה, השוו. ואחר כך שמעו את Plateau בשקט, ודמיינו מדבר בצהריים.''',
], [
('Plateau', 'רמה מסתורית במדבר, עם דלי, סמרטוט ושאלות בלי תשובה.'),
('Lake of Fire', 'שיר מצחיק־מפחיד על המקום שאליו הולכים אנשים רעים אחרי המוות.'),
('Oh, Me', 'שיר שקט וחלומי, עם גיטרה מתפתלת וקול רך ומהורהר.'),
])

add(531, [
'''קלצ׳ר קלאב באו מלונדון, ובחזית עמד בוי ג׳ורג׳, זמר עם קול חם של סול, איפור, צמות ובגדים צבעוניים, שהפך תוך זמן קצר לאחד האנשים המוכרים בעולם. הלהקה שילבה פופ בריטי עם סול, רגאיי ומוזיקת מוטאון. Colour by Numbers, האלבום השני שלהם, יצא בסוף 1983, הגיע למקום הראשון באנגליה ולמקום השני באמריקה.''',
'''המוזיקה עליזה, חמה ומלוטשת: כלי נשיפה, קולות רקע של סול, בס רגאיי וקולו הרך של ג׳ורג׳. Karma Chameleon, הלהיט הגדול, עם מפוחית שמחה וקצב כמעט של קאנטרי, הוא שיר על אדם שמשנה צבעים כמו זיקית ולא יודע מה הוא באמת. הוא הגיע למקום הראשון באנגליה ובאמריקה. Church of the Poison Mind הוא שיר סול סוחף, עם הזמרת הלן טרי שעונה לג׳ורג׳ בקול עוצמתי. Miss Me Blind רך ומתגעגע, ו־It's a Miracle עליז ומקפץ. Victims היא בלדה דרמטית ואיטית עם פסנתר, על אהבה שפוגעת בשני הצדדים.''',
'''קלצ׳ר קלאב היו מהלהקות המצליחות בעולם באותן שנים. בוי ג׳ורג׳, עם המראה שלו, שבר מוסכמות של גבריות ונשיות, ופתח את הדרך לאמנים רבים שבאו אחריו. האלבום נמכר במיליוני עותקים, אבל זמן קצר אחר כך הלהקה התחילה להתפרק, בין השאר בגלל מתחים אישיים ובעיות של ג׳ורג׳ עם סמים. שנים אחר כך הלהקה התאחדה, וג׳ורג׳ הפך גם לדיג׳יי ולצלם.''',
'''שמעו את Karma Chameleon, ואחריו את Church of the Poison Mind, ושימו לב כמה מוזיקת סול אמריקאית יש בלהקת פופ בריטית.''',
], [
('Karma Chameleon', 'אדם שמשנה צבעים כמו זיקית, עם מפוחית שמחה וקצב של קאנטרי.'),
('Church of the Poison Mind', 'שיר סול סוחף, עם הזמרת הלן טרי שעונה בקול עוצמתי.'),
('Victims', 'בלדה דרמטית ואיטית עם פסנתר, על אהבה שפוגעת בשני הצדדים.'),
])

add(532, [
'''פרנקי גוז טו הוליווד באו מליברפול, להקה של זמר בשם הולי ג׳ונסון ועוד ארבעה חברים, עם תדמית פרובוקטיבית ומחוצפת. הם חתמו בחברת תקליטים חדשה, ZTT, של המפיק טרבור הורן (שהפיק גם את אלבום 496) ושל העיתונאי פול מורלי, שהבינו איך להפוך כל צעד שלהם לשערורייה. Welcome to the Pleasuredome, אלבום כפול, יצא בסוף 1984, אחרי שלושה סינגלים שכולם הגיעו למקום הראשון באנגליה.''',
'''הצליל עצום ומפוצץ: סינתיסייזרים, תופים אלקטרוניים, בס עמוק, מקהלות ותזמורות, הכל בהפקה של הורן, שעבד חודשים על כל שיר. Relax, שה־BBC אסר להשמיע בגלל מילותיו הרמזניות, הפך דווקא בזכות האיסור ללהיט ענק. Two Tribes מתאר את המלחמה הקרה כמו קרב היאבקות בין שני מנהיגים, בקצב דוהר ומאיים. The Power of Love היא בלדה תזמורתית גדולה ורגשנית. שיר הנושא נמשך כרבע שעה, ויש באלבום גם גרסאות מפתיעות לשירים של אחרים, כמו Born to Run של ספרינגסטין (אלבום 335).''',
'''באנגליה של 1984 פרנקי היו בכל מקום: חולצות עם הכיתוב "Frankie Say Relax" נמכרו במיליונים, והלהקה הייתה רק השנייה בתולדות המצעד, אחרי להקה נוספת מליברפול שנים קודם, ששלושת הסינגלים הראשונים שלה הגיעו למקום הראשון. אבל ההצלחה הייתה קצרה, והלהקה התפרקה אחרי אלבום נוסף.''',
'''התחילו ב־Two Tribes, ושימו לב לבס ולתופים. אחר כך שמעו את The Power of Love בשקט, ותבינו כמה רחב היה הטווח של הלהקה המחוצפת הזאת.''',
], [
('Two Tribes', 'המלחמה הקרה כמו קרב היאבקות בין מנהיגים, בקצב דוהר ומאיים.'),
('Relax', 'הלהיט שה־BBC אסר להשמיע, והפך דווקא בזכות זה לענק.'),
('The Power of Love', 'בלדה תזמורתית גדולה ורגשנית על אהבה, להיט שלישי ברציפות במקום הראשון.'),
])

add(533, [
'''ראן־די.אם.סי. היו שלושה חברים משכונת הוליס שבקווינס, ניו יורק: ג׳וזף סימונס (ראן), דאריל מקדניאלס (די.אם.סי.) והדיג׳יי ג׳אם מאסטר ג׳יי. בזמן שראפרים אחרים לבשו תלבושות נוצצות של דיסקו, הם הופיעו בבגדי רחוב: מעילי עור, כובעים ונעלי ספורט בלי שרוכים. את הלהקה ניהל ראסל סימונס, אחיו הגדול של ראן, שהקים בהמשך את חברת Def Jam. האלבום הראשון שלהם, שיצא ב־1984, שינה את ההיפ הופ.''',
'''המוזיקה פשוטה וקשוחה: מכונת תופים חזקה, סקרץ׳ של ג׳ם מאסטר ג׳יי, ושני ראפרים שצועקים את החרוזים בתורות, כמעט בלי מוזיקה מתחת. It's Like That מתאר את המציאות הקשה של העוני והאבטלה בלי סנטימנטים, ו־Sucker M.C.'s לועג לראפרים מזויפים, על מקצב תופים בלבד. Rock Box מוסיף גיטרה חשמלית של רוק כבד, וחיבור כזה בין ראפ לרוק היה אז חדש לגמרי. Hard Times, הפותח, מדבר על תקופה קשה ועל הצורך להיאבק.''',
'''זה היה אלבום הראפ הראשון שנמכר בחצי מיליון עותקים באמריקה, והקליפ של Rock Box היה מהקליפים הראשונים של ראפ שהוצגו ב־MTV. שנתיים אחר כך הם הקליטו יחד עם אירוסמית׳ את Walk This Way, וחיברו סופית בין ראפ לרוק. הצליל הקשוח והמינימליסטי שלהם הפך לבסיס של ההיפ הופ של אמצע שנות השמונים, והמראה שלהם, עם נעלי האדידס, הפך לסמל של תרבות הרחוב.''',
'''שמעו את The Message של גרנדמאסטר פלאש (אלבום 498) ואחריו את Sucker M.C.'s, ותשמעו כמה מעט מוזיקה נשארה, וכמה עוצמה.''',
], [
("It's Like That", 'המציאות הקשה של עוני ואבטלה, בלי סנטימנטים, על מקצב חזק.'),
("Sucker M.C.'s", 'לעג לראפרים מזויפים, על מקצב תופים קשוח בלבד, בלי שום מוזיקה נוספת.'),
('Rock Box', 'ראפ עם גיטרה חשמלית של רוק כבד, חיבור חדש לגמרי בזמנו.'),
])

add(534, [
'''שאדה אדו נולדה בניגריה וגדלה באנגליה, למדה עיצוב אופנה ועבדה כדוגמנית, עד שהתחילה לשיר בלהקת פאנק לטיני. עם שלושה מחברי הלהקה, הסקסופוניסט והגיטריסט סטיוארט מתיומן, הקלידן אנדרו הייל והבסיסט פול דנמן, היא הקימה להקה שנקראה בשמה, Sade. Diamond Life, האלבום הראשון, יצא ב־1984.''',
'''המוזיקה רגועה, אלגנטית וחמה: סול, ג׳אז ובוסה נובה, עם סקסופון רך, בס עגול, תופים עדינים, וקולה של שאדה, נמוך, שקט ומלא, שלא צריך לצעוק כדי לרגש. Smooth Operator, הלהיט המפורסם, מתאר נוכל מקסים שמטייל בין ערים ושובר לבבות, עם סקסופון שמתלווה כמו צל. Your Love Is King הוא שיר אהבה פשוט ומלכותי, ו־Hang On to Your Love קצבי יותר. When Am I Going to Make a Living מספר על צעירים שרוצים לפרנס את עצמם בזמן אבטלה, ו־Why Can't We Live Together חותם בגרסה לשיר סול ישן על שלום.''',
'''Diamond Life הפך את שאדה לכוכבת עולמית, והוא נבחר לאלבום השנה בפרסי המוזיקה הבריטיים. בשנים הבאות הלהקה הוציאה אלבומים לאט, עם הפסקות של שנים, אבל כל אחד מהם הצליח מאוד. הצליל הרגוע והמוקפד שלה נשמע עד היום בבתי קפה, במסעדות ובמכוניות בכל העולם. שאדה עצמה כמעט לא מתראיינת, ומעדיפה שהמוזיקה תדבר בשבילה.''',
'''זה אלבום לערב רגוע, עם כוס יין או ספר. ואם אהבתם את What's Going On של מרווין גיי (אלבום 208), תמצאו כאן את אותו חום, בגרסה שקטה ואירופית יותר.''',
], [
('Smooth Operator', 'נוכל מקסים ששובר לבבות בין ערים, עם סקסופון כמו צל.'),
('Your Love Is King', 'שיר אהבה פשוט ומלכותי, בקול נמוך ושקט וסקסופון רך.'),
('When Am I Going to Make a Living', 'צעירים שרוצים לפרנס את עצמם בזמן אבטלה, בקצב רגוע.'),
])

add(535, [
'''קוקטו טווינס באו מגריינג׳מות׳, עיירת תעשייה קטנה בסקוטלנד. הזמרת אליזבת פרייזר והגיטריסט רובין גאת׳רי, שהיו גם זוג, הצטרפו בהמשך לבסיסט סיימון ריימונד. הם הקליטו בחברת התקליטים הקטנה 4AD, שהתמחתה במוזיקה חלומית ואפלה, ו־Treasure, האלבום השלישי שלהם, יצא ב־1984.''',
'''הקסם הוא בקול של פרייזר: הוא גבוה, צלול ומרחף, ולעתים קרובות היא שרה מילים שאינן בשום שפה, צלילים שהיא ממציאה, כך שהקול הופך לעוד כלי נגינה. מתחתיה הגיטרה של גאת׳רי, מלאה בהדהודים ואפקטים, יוצרת ענן של צלילים, יחד עם מכונת תופים ובס מלודי. לשירים יש שמות של דמויות מהמיתולוגיה ומהאגדות: Lorelei, על הבתולה שמושכת ספנים אל הסלעים, הוא שיר מהיר ונוצץ. Persephone, על מלכת השאול, דרמטי וסוער. Ivo, הפותח, נקרא על שם מנהל חברת התקליטים, ו־Pandora עדין ומלנכולי.''',
'''Treasure נחשב לאחד האלבומים שהגדירו את מה שנקרא אחר כך "דרים פופ", מוזיקה חלומית ומעורפלת, והשפיע על להקות רבות של שוגייז ושל רוק אלטרנטיבי. אמנים מגוונים מאוד, מזמרים ועד מפיקים של מוזיקה אלקטרונית, סיפרו כמה הושפעו מהקול של פרייזר. פרייזר עצמה שרה מאוחר יותר גם עם להקות אחרות, ובהן מאסיב אטאק, בשיר Teardrop המפורסם. העטיפות של 4AD, עם צילומים מטושטשים וחלומיים, התאימו בדיוק לצליל הזה. פרייזר וגאת׳רי נפרדו בהמשך, והלהקה התפרקה בסוף שנות התשעים.''',
'''אל תנסו להבין את המילים, אין מה להבין. שמעו באוזניות, בעיניים עצומות, ותנו לקול לעשות את שלו. התחילו ב־Lorelei.''',
], [
('Lorelei', 'שיר מהיר ונוצץ על הבתולה שמושכת ספנים אל הסלעים.'),
('Persephone', 'דרמטי וסוער, על מלכת השאול, עם גיטרה כמו ענן.'),
('Pandora (For Cindy)', 'שיר עדין ומלנכולי, עם הקול הגבוה והמרחף של פרייזר ומילים שאינן בשום שפה.'),
])

add(536, [
'''מיינור ת׳רט באו מוושינגטון הבירה, להקת הארדקור מהירה וזועמת, עם הזמר איאן מקיי, שהקים גם את חברת התקליטים העצמאית Dischord. מקיי היה חבר ילדות של הנרי רולינס, שהפך לזמר של בלאק פלאג (אלבום 486). Out of Step, האלבום היחיד של הלהקה, יצא ב־1983, תשעה שירים בכעשרים דקות.''',
'''המוזיקה מהירה, חדה ומדויקת, מהירה יותר ממה שרוב הלהקות ידעו לנגן אז, עם קולו הצועק של מקיי, שכל מילה שלו ברורה. אבל מה שמיוחד הוא המילים: מקיי שר על חברות, על בגידה, על אחריות אישית ועל הרצון לחיות נקי, בלי אלכוהול ובלי סמים, בסצנה שבה כולם השתכרו. שיר הנושא מכריז "אני לא מעשן, לא שותה", ובאמצעו מקיי עוצר ומסביר שאין כאן חוקים לאחרים, רק בחירה אישית. Betray עוסק בחבר שבגד, ו־Little Friend מתאר בכעס מי שמנסה לשנות אותך. Cashing In חותם בלעג מצחיק לעצמם, ללהקה שלכאורה מוכרת את עצמה.''',
'''מיינור ת׳רט הולידו את תנועת ה"סטרייט אדג׳": צעירים שבחרו לא לשתות ולא להשתמש בסמים, ושציירו X על כף היד. הלהקה התפרקה ב־1983, ומקיי הקים אחר כך את Fugazi, אחת הלהקות החשובות של הרוק העצמאי האמריקאי, שמכרה כרטיסים זולים ולא חתמה בחברות גדולות. ההופעות שלהם היו קצרות, מהירות וחסרות כל קישוט, בדיוק כמו התקליט.''',
'''קראו את המילים בזמן ההאזנה, כי בשבילן נכתבו השירים. ואחר כך שמעו את Damaged של בלאק פלאג (אלבום 486), ותשמעו שני צדדים של אותו זעם.''',
], [
('Out of Step', 'הכרזה על חיים נקיים, עם עצירה באמצע להסביר שזו בחירה אישית.'),
('Betray', 'שיר מהיר וזועם על חבר שבגד, עם צעקות ברורות.'),
('Cashing In', 'לעג מצחיק של הלהקה לעצמה, ללהקה שלכאורה מוכרת את עצמה.'),
])

add(537, [
'''ואן היילן (אלבום 415) היו כבר אחת מלהקות הרוק הגדולות באמריקה, עם הגיטריסט המהפכני אדי ואן היילן והזמר השובב דייוויד לי רות׳. אבל אדי רצה לנסות משהו חדש: סינתיסייזר. הוא בנה אולפן בבית שלו, ושם הקליטה הלהקה את 1984, שיצא בתחילת אותה שנה. רק Thriller (אלבום 508), שבו אדי ניגן סולו גיטרה בשיר Beat It, הקדים אותו במצעד האמריקאי.''',
'''Jump, הלהיט הגדול, בנוי על ריף של סינתיסייזר שמח ופשוט במקום גיטרה, והגיע למקום הראשון באמריקה. הרבה מעריצים ותיקים כעסו, אבל השאר רקדו. מעבר לו, האלבום הוא רוק כבד וחגיגי בסגנון הרגיל של הלהקה: Panama הוא שיר מהיר ופרוע על מכונית מירוץ ועל בחורה, ו־Hot for Teacher נפתח בתופים כבדים ודוהרים של אלכס ואן היילן, ומספר בהומור על תלמידים שמתאהבים במורה. I'll Wait רך יותר, עם סינתיסייזר אפל, ו־Drop Dead Legs מתנדנד באיטיות. רות׳ צועק, צוחק ומדבר בין השורות, כמו מנחה של מסיבה.''',
'''1984 היה השיא של ההרכב המקורי: אחרי סיבוב ההופעות עזב רות׳, והלהקה המשיכה עם זמר אחר. הקליפים המצחיקים של האלבום, ובמיוחד זה של Hot for Teacher, שודרו בלי הפסקה ב־MTV, והוא נמכר בעשרה מיליון עותקים ויותר. העטיפה, ציור של תינוק מלאך שמעשן סיגריה, עוררה גם היא מחלוקת, כמו כמעט כל דבר שהלהקה עשתה באותן שנים.''',
'''שמעו את Eruption מהאלבום הראשון (415), ואחר כך את Jump. אותו גיטריסט, שש שנים אחר כך, והפעם הכוכב הוא דווקא הקלידים.''',
], [
('Jump', 'ריף סינתיסייזר שמח במקום גיטרה, שהכעיס מעריצים ותיקים והגיע למקום הראשון.'),
('Hot for Teacher', 'תופים דוהרים בפתיחה, ותלמידים שמתאהבים במורה, בהומור פרוע וגס.'),
('Panama', 'שיר מהיר ופרוע על מכונית מירוץ ועל בחורה, עם ריף חגיגי.'),
])

add(538, [
'''אחרי ההצלחה של 1999 (אלבום 497), פרינס רצה להיות כוכב קולנוע. הוא כתב וכיכב בסרט Purple Rain, על מוזיקאי צעיר ממיניאפוליס עם אב אלים, שמתחרה בלהקות אחרות במועדון מקומי ומנסה להגיע לקהל. האלבום, פסקול הסרט, יצא ב־1984 עם להקתו החדשה, The Revolution, שבה ניגנו גם הגיטריסטית וונדי מלווין והקלידנית ליסה קולמן.''',
'''המוזיקה עוברת בין רוק, פאנק, פופ ובלדות, והכל נשמע גדול ומלא חיים. Let's Go Crazy, הפותח, נפתח בדרשה של פרינס על החיים ועל המוות, ומתפוצץ לרוק מהיר עם סולו גיטרה מטורף. When Doves Cry, הלהיט הגדול, הוא שיר מוזר במיוחד, בלי גיטרה בס בכלל, על אהבה שחוזרת על טעויות ההורים. Purple Rain, השיר החותם, הוא בלדת רוק ארוכה ומרגשת, שהוקלטה בחלקה בהופעה במועדון במיניאפוליס, עם סולו גיטרה שנמשך דקות ארוכות. I Would Die 4 U מהיר ואלקטרוני, ו־The Beautiful Ones היא בלדה שמתחילה בעדינות ונגמרת בצעקה.''',
'''האלבום נשאר כחצי שנה במקום הראשון באמריקה, והסרט זכה בפרס אוסקר על המוזיקה. שיר אחד ממנו, Darling Nikki, עם מילים בוטות, עורר מחאה שהובילה למדבקות "אזהרה להורים" על תקליטים. פרינס הפך לאחד האמנים הגדולים בעולם, וגם להקתו The Revolution הפכה למפורסמת, עם וונדי וליסה שהמשיכו אחר כך כצמד מצליח.''',
'''שמעו את Purple Rain עד הסוף, עם הסולו. ואחר כך את When Doves Cry, ושימו לב שאין בו בס בכלל, אבל אין צורך.''',
], [
('When Doves Cry', 'שיר מוזר בלי גיטרה בס, על אהבה שחוזרת על טעויות ההורים.'),
('Purple Rain', 'בלדת רוק ארוכה ומרגשת, עם סולו גיטרה של דקות ארוכות.'),
("Let's Go Crazy", 'דרשה על החיים והמוות, שמתפוצצת לרוק מהיר וסולו מטורף.'),
])

add(539, [
'''הרפלייסמנטס באו ממיניאפוליס, אותה עיר של פרינס, אבל היו ההפך הגמור ממנו: להקה פרועה, מבולגנת ושיכורה לעיתים קרובות, שהופעותיה היו יכולות להיות גאוניות או אסון. הכותב והזמר פול וסטרברג, האחים בוב וטומי סטינסון (טומי הצטרף לבס כשהיה רק בן שתים־עשרה) והמתופף כריס מארס. Let It Be, האלבום השלישי שלהם, יצא ב־1984, ושמו הוא בדיחה על האלבום המפורסם של הביטלס.''',
'''המוזיקה עוברת בין פאנק מהיר ורועש לבין שירים רכים וכנים, עם גיטרות חשמליות פשוטות וקולו הצרוד של וסטרברג. הוא כותב על בדידות, על התבגרות ועל מבוכה, בכנות נדירה. I Will Dare, הפותח, הוא שיר פופ קליל ושמח, עם סולו גיטרה אורח של פיטר באק מ־R.E.M. (אלבום 518). Unsatisfied הוא זעקה כואבת של מי שלא מוצא את מקומו, ו־Androgynous הוא שיר פסנתר עדין על זוג צעיר שלא מתאים לתבניות של גבר ואישה. Sixteen Blue מתאר את הקושי להיות בן שש־עשרה, ו־Answering Machine, שחותם, הוא שיר על הבדידות של מי שמנסה לדבר עם משיבון.''',
'''הרפלייסמנטס מעולם לא הפכו לכוכבים גדולים, אבל השפיעו מאוד על הרוק האלטרנטיבי של שנות התשעים, ורבים ראו בהם את הלהקה האמריקאית החשובה של שנות השמונים שלא הצליחה. Let It Be נחשב לאלבום הטוב ביותר שלהם.''',
'''שמעו את Unsatisfied ואת Androgynous, שני שירים שקטים יחסית. אחר כך שמעו את שאר האלבום, ותבינו איך להקה רועשת כל כך יכולה להיות עדינה כל כך.''',
], [
('Unsatisfied', 'זעקה כואבת של מי שלא מוצא את מקומו בעולם.'),
('Androgynous', 'שיר פסנתר עדין על זוג צעיר שלא מתאים לתבניות.'),
('I Will Dare', 'שיר פופ קליל ושמח, עם סולו אורח של פיטר באק.'),
])

add(540, [
'''ב־1982, בשיא ההצלחה של הג׳אם (אלבומים 402 ו־471), פול ולר פירק את הלהקה, כי פחד שתהפוך לחזרה על עצמה. הוא הקים צמד חדש עם הקלידן מיק טלבוט, The Style Council, שבו יוכל לנגן כל מה שהוא אוהב: סול, ג׳אז, בוסה נובה ופופ אירופי. Café Bleu, האלבום הראשון שלהם, יצא ב־1984, ובאמריקה נקרא My Ever Changing Moods.''',
'''האלבום מבולבל במכוון ומקסים: כמה קטעים כליים קצרים של פסנתר ג׳אז, שירי סול עם כלי נשיפה, בוסה נובה רכה, ואפילו שיר ראפ. ולר שר בקול חם, לפעמים מתחלף עם זמרות אורחות. My Ever Changing Moods, הלהיט הגדול, הוא שיר סול קצבי ושמח, עם כלי נשיפה. The Paris Match, ששרה טרייסי ת׳ורן מאברית׳ינג בוט דה גירל, הוא שיר ג׳אז רך ועצוב, כמו בית קפה בפריז בגשם. You're the Best Thing היא בלדת סול מתוקה ואיטית, ו־Headstart for Happiness שמח ואופטימי. Blue Café ו־Mick's Blessings הם קטעים כליים קצרים, כמו נשימה בין השירים.''',
'''מעריצים רבים של הג׳אם לא הבינו את השינוי, אבל האלבום הצליח מאוד באנגליה, והראה שוולר הוא אמן שלא מפחד להשתנות. ברבות השנים השפיע הסגנון שלו על להקות שחיברו בין פופ בריטי לג׳אז ולסול, וגם על האופנה, עם חולצות מכופתרות וסוודרים איטלקיים.''',
'''שמעו את That's Entertainment של הג׳אם (אלבום 471), ואחריו את The Paris Match. אותו כותב, שלוש שנים אחר כך, בעולם אחר לגמרי.''',
], [
('My Ever Changing Moods', 'הלהיט הגדול, שיר סול קצבי ושמח עם כלי נשיפה.'),
('The Paris Match', 'ג׳אז רך ועצוב בקולה של טרייסי ת׳ורן, כמו בית קפה בפריז בגשם.'),
("You're the Best Thing", 'בלדת סול מתוקה ואיטית, בקולו החם של ולר, עם כלי נשיפה רכים.'),
])

add(541, [
'''טינה טרנר הייתה כוכבת כבר בשנות השישים, כחלק מהצמד אייק וטינה טרנר, עם קול עוצמתי ורגליים שלא הפסיקו לרקוד. אבל מאחורי הקלעים היא סבלה מאלימות קשה מבעלה אייק, וב־1976 ברחה ממנו, עם מעט כסף ובלי קריירה. בשנים שאחר כך הופיעה בעיקר במועדונים קטנים, עד ש־Private Dancer, שיצא ב־1984 כשהייתה בת ארבעים וארבע, החזיר אותה לפסגה.''',
'''האלבום הוא פופ־רוק מלוטש של שנות השמונים, עם סינתיסייזרים, גיטרות וסקסופון, אבל במרכזו קולה של טרנר: מחוספס, חזק, מלא בניסיון חיים. What's Love Got to Do with It, הלהיט הגדול, הוא שיר על אישה שמסרבת להתאהב שוב, כי אהבה היא "רגש מיד שנייה", והוא הגיע למקום הראשון באמריקה. Private Dancer, שכתב מארק נופלר מדייר סטרייטס (אלבום 551), מספר על רקדנית שחולמת על חיים אחרים. Let's Stay Together היא גרסה לשיר הסול של אל גרין, שהפיקו חברי Heaven 17 (אלבום 480), ובאמת התחילה את הקאמבק. Better Be Good to Me נשמע כמו אזהרה תקיפה לגבר.''',
'''Private Dancer נמכר במיליוני עותקים, זיכה את טרנר בכמה פרסי גראמי והפך אותה לאחת הזמרות הגדולות בעולם, הפעם בזכות עצמה. הסיפור שלה הפך לסמל של אישה שקמה מחדש, ובהמשך גם לסרט ולמחזמר.''',
'''שמעו את What's Love Got to Do with It, ותחשבו על מי ששרה אותו ועל מה שעברה. ואחר כך שמעו את Let's Stay Together, ותבינו למה כולם חיכו לקאמבק הזה.''',
], [
("What's Love Got to Do with It", 'אישה שמסרבת להתאהב שוב, כי אהבה היא רגש מיד שנייה.'),
('Private Dancer', 'רקדנית שחולמת על חיים אחרים, שיר של מארק נופלר.'),
("Let's Stay Together", 'גרסה לשיר הסול של אל גרין, שהתחילה את הקאמבק.'),
])

add(542, [
'''אחרי Porcupine (אלבום 525), הקשה והמתוח, אקו והבאנימן רצו משהו יפה, רחב ורומנטי. הם הקליטו חלק מהאלבום בפריז, עם תזמורת של כלי מיתר, ובחרו צליל אקוסטי ושקט יותר. Ocean Rain יצא ב־1984, ומשרד הפרסום של הלהקה, ברוח היהירות של הזמר איאן מקולוך, הכריז עליו כ"אלבום הגדול ביותר שנוצר אי פעם".''',
'''הצליל עשיר וחלומי: כינורות וצ׳לו, גיטרות אקוסטיות וחשמליות מתפתלות, בס עמוק, וקולו של מקולוך, שנשמע כאן רך ודרמטי מאי פעם. יש תחושה של ים, של לילה ושל מסע ארוך, וגם העטיפה מראה את הלהקה בסירה קטנה על מים כהים בתוך מערה. The Killing Moon, השיר המפורסם באלבום, הוא בלדה אפלה ויפה על גורל ועל אהבה, עם ירח שמאיר את הכל ובס שמתנדנד כמו גלים. הוא נבחר בעיני רבים לשיר הטוב בתולדות הלהקה, והופיע שנים אחר כך בסרט "דוני דארקו". Seven Seas קליל ומשחקי, Silver, הפותח, שמח ונוצץ, ו־Nocturnal Me אפל ותזמורתי. שיר הנושא, שחותם, איטי ועצוב, כמו גשם על הים.''',
'''Ocean Rain נחשב בעיני רבים לאלבום הטוב ביותר של הלהקה, ולאחד מאלבומי הפוסט־פאנק הבריטי היפים ביותר. אחריו הלהקה התחילה להתפרק, ובסוף שנות השמונים מקולוך עזב, והמתופף פיט דה פרייטאס נהרג בתאונת אופנוע.''',
'''שמעו את Crocodiles (אלבום 462), את Porcupine (אלבום 525) ואת Ocean Rain, אחד אחרי השני, ותשמעו להקה שגדלה מגיטרות חדות לתזמורת שלמה. ואת The Killing Moon שמעו בלילה.''',
], [
('The Killing Moon', 'בלדה אפלה ויפה על גורל ואהבה, עם בס שמתנדנד כמו גלים.'),
('Seven Seas', 'שיר קליל ומשחקי על שבעה ימים, עם כינורות וגיטרה אקוסטית.'),
('Ocean Rain', 'השיר החותם, איטי ועצוב, כמו גשם על הים בלילה.'),
])

add(543, [
'''המינוטמן היו שלישייה מסן פדרו, עיר נמל ליד לוס אנג׳לס: הגיטריסט והזמר די. בון, הבסיסט מייק וואט והמתופף ג׳ורג׳ הרלי. הם ניגנו פאנק, אבל עם השפעות של ג׳אז, פאנק אמריקאי, פולק ורוק קלאסי, והשירים שלהם קצרים מאוד, לעיתים פחות מדקה. Double Nickels on the Dime, אלבום כפול עם יותר מארבעים שירים, יצא ב־1984 בחברת SST של בלאק פלאג (אלבום 486).''',
'''השם הוא בדיחה: זמר רוק בשם סמי הגר התלונן בשיר על המגבלה של 55 מייל לשעה, והמינוטמן הכריזו שהם נוסעים בדיוק במהירות המותרת, 55, על הכביש. העטיפה מראה את וואט נוהג. המוזיקה מגוונת להפליא: שירים פוליטיים, שירי אהבה, קטעי ג׳אז, ניסויים ושירים מצחיקים. History Lesson – Part II הוא שיר עדין ויפה על החברות בלהקה, עם המשפט "הלהקה שלנו יכולה להיות החיים שלך". Corona הוא שיר קליל ומהיר עם גיטרה שמחה, על עיירה קטנה במקסיקו. Political Song for Michael Jackson to Sing לועג בחיוך לפופ חסר משמעות, ו־This Ain't No Picnic מתאר עבודה קשה תחת בוס.''',
'''באותה תקופה יצא גם אלבום כפול של להקה מאותה חברת תקליטים, הוסקר דו, ושניהם יחד הראו שפאנק יכול להיות גם שאפתני ומגוון. בסוף 1985 נהרג די. בון בתאונת דרכים, בגיל עשרים ושבע, והלהקה הסתיימה. עם השנים התברר כמה היא השפיעה על הרוק העצמאי האמריקאי, והמשפט מהשיר הפך לשם של ספר חשוב על התקופה.''',
'''אל תנסו לשמוע את הכל בבת אחת. התחילו ב־History Lesson – Part II, ואחר כך דפדפו בין השירים הקצרים כמו באלבום תמונות.''',
], [
('History Lesson – Part II', 'שיר עדין ויפה על חברות בלהקה ועל חלום משותף.'),
('Corona', 'שיר קליל ומהיר עם גיטרה שמחה, על עיירה קטנה במקסיקו.'),
('Political Song for Michael Jackson to Sing', 'לעג בחיוך לפופ חסר משמעות, בפחות משתי דקות של רעש ושמחה.'),
])

add(544, [
'''לויד קול היה סטודנט לספרות ולפילוסופיה בגלזגו, שאהב את בוב דילן, את לו ריד ואת הסופרים האמריקאים הגדולים. עם חבריו הוא הקים את The Commotions, וב־1984 הוציאו את Rattlesnakes, אלבום של פופ גיטרות שבו המילים חשובות לא פחות מהמנגינות. הוא נכנס לעשרים הגדולים במצעד הבריטי.''',
'''המוזיקה רכה ומצלצלת: גיטרות נקיות, בס חם, אורגן וכלי מיתר מעטים שעיבדה אן דאדלי, שעבדה גם עם ABC (אלבום 496). קול שר בקול נמוך ורגוע, כמעט מדבר, על צעירות חכמות ונוגות, על אהבה שלא מסתדרת ועל ספרים וסרטים. המילים מלאות שמות של סופרים ושחקנים, ונשמעות כמו סיפורים קצרים של סטודנט רומנטי. Perfect Skin, הפותח, מתאר בחורה יפה ומסובכת בקצב קופצני. Forest Fire הוא שיר אהבה בוער ונוגה, עם סולו גיטרה מתפתל. שיר הנושא מתאר צעירה חכמה ונוגה, שקוראת ספרים ורואה סרטים ישנים, ו־Are You Ready to Be Heartbroken? שואל בחיוך עצוב אם מישהו באמת מוכן לשבור את ליבו.''',
'''Rattlesnakes לא הפך ללהיט גדול, אבל הוא אהוב מאוד על מי שגילה אותו, ונחשב לאחד מאלבומי הפופ האינטליגנטיים של שנות השמונים. הוא השפיע על להקות רבות של פופ גיטרות בריטי, שלמדו ממנו שאפשר לשיר על ספרות בלי להישמע מתנשאים. קול עבר בהמשך לניו יורק, והמשיך בקריירת סולו שקטה ואישית.''',
'''שמעו אותו ברצף, וקראו את המילים. ואם אתם אוהבים את בוב דילן (אלבום 58) ואת הסמית׳ס, תרגישו כאן בבית.''',
], [
('Perfect Skin', 'בחורה יפה ומסובכת שהיא לא מוכנה לאהבה, בקצב קופצני ובגיטרות מצלצלות.'),
('Forest Fire', 'שיר אהבה בוער ונוגה על אהבה שאי אפשר לכבות, עם סולו גיטרה מתפתל.'),
('Are You Ready to Be Heartbroken?', 'שאלה בחיוך עצוב: מי באמת מוכן לשבור את ליבו?'),
])

add(545, [
'''יוסו נ׳דור נולד בדקאר, בירת סנגל, למשפחה של גריוטים, משוררים־זמרים שמספרים במשך דורות את ההיסטוריה של העם. כבר כנער הוא היה כוכב מקומי, עם קול גבוה וצלול שיכול לעלות לגבהים מדהימים. עם להקתו, Le Super Étoile de Dakar, הוא פיתח את סגנון המבלקס: מוזיקת פופ סנגלית, שמחברת תופים מסורתיים מקומיים עם גיטרות, סקסופון וקלידים. Immigrés יצא באמצע שנות השמונים, והגיע גם לחנויות התקליטים באירופה.''',
'''האלבום כולל ארבעה שירים ארוכים בלבד, וכל אחד מהם נמשך כמה דקות טובות ונבנה לאט. התופים, ובמיוחד תוף הסבאר הסנגלי, מדברים כמעט כמו קול נוסף, והגיטרות מתפתלות בקצב מהיר. קולו של נ׳דור עולה מעל כל זה, כמו קריאה. שיר הנושא מדבר אל המהגרים הסנגלים בצרפת, שעזבו את ביתם כדי לעבוד, ומזכיר להם את המולדת. Pitche Mi קצבי ושמח, ו־Taaw ו־Badou ממשיכים באותה אנרגיה, עם קריאות ותשובות בין הזמר ללהקה.''',
'''פיטר גבריאל (אלבום 459) שמע את המוזיקה של נ׳דור, התאהב בה והזמין אותו לשיר איתו ב־In Your Eyes, ולהופיע בסיבובי הופעות. כך הפך נ׳דור לאחד האמנים האפריקאים המוכרים בעולם. בהמשך הוא שר עם נֶנֶה צ׳רי את 7 Seconds, ואף כיהן כשר בממשלת סנגל.''',
'''זה אלבום לתת לו זמן. שמעו את שיר הנושא עד הסוף, ותנו לתופים להוביל אתכם. ואם אהבתם את Zombie של פלה קוטי (אלבום 365), תשמעו כאן עוד צד של אפריקה המערבית.''',
], [
('Immigrés / Bitim Rew', 'שיר ארוך למהגרים הסנגלים בצרפת, על המולדת שנשארה מאחור.'),
('Pitche Mi', 'שיר קצבי ושמח, עם תופי סבאר שמדברים כמו קול נוסף.'),
('Taaw', 'קריאות ותשובות בין הזמר ללהקה, בקצב מהיר וסוחף של תופי סבאר.'),
])

add(546, [
'''חלק מהשירים ב־Born in the U.S.A. נכתבו באותם ימים שבהם הקליט ברוס ספרינגסטין את Nebraska השקט (אלבום 511), בבית. אבל הפעם הוא לקח אותם ללהקה שלו, האי סטריט בנד, ונתן להם צליל גדול, עם תופים רועמים, סינתיסייזרים וגיטרות. האלבום יצא ב־1984 והפך להצלחה הגדולה ביותר שלו: שבעה שירים ממנו נכנסו לעשירייה הראשונה במצעד האמריקאי.''',
'''שיר הנושא, הפותח, נשמע כמו המנון פטריוטי, עם פזמון שכל אצטדיון צועק. אבל המילים מספרות על חייל משוחרר ממלחמת וייטנאם, שחוזר הביתה ולא מוצא עבודה ולא מקום. רבים, וביניהם פוליטיקאים, הבינו את השיר הפוך. Dancing in the Dark, עם סינתיסייזר מקפץ, הוא שיר על תסכול ועל רצון לשנות את החיים, וגם להיט ריקוד גדול. Glory Days מתאר בהומור אנשים שמתגעגעים לימי התהילה של התיכון. I'm on Fire הוא שיר תשוקה שקט ומחשמל, ו־My Hometown, שחותם, מספר על עיר קטנה שהמפעלים בה נסגרים.''',
'''האלבום נמכר בעשרות מיליוני עותקים, והפך את ספרינגסטין לכוכב רוק ענק, עם הופעות של שלוש וארבע שעות באצטדיונים. גם הקליפ של Dancing in the Dark, שבו ספרינגסטין מעלה לבמה צעירה מהקהל, הפך למפורסם, והיא עצמה הפכה לשחקנית מוכרת. העטיפה, שבה הוא עומד בג׳ינס מול דגל אמריקה, הפכה לאחד הסמלים של שנות השמונים.''',
'''שמעו את שיר הנושא וקראו את המילים, ואחר כך את Nebraska (אלבום 511). אותם נושאים, אותה תקופה, ושני צלילים הפוכים לגמרי.''',
], [
('Born in the U.S.A.', 'נשמע כמו המנון פטריוטי, אבל מספר על חייל משוחרר שאין לו מקום.'),
("I'm on Fire", 'שיר תשוקה שקט ומחשמל, עם סינתיסייזר עדין וקול כמעט לוחש.'),
('My Hometown', 'עיר קטנה שהמפעלים בה נסגרים, ואב שמראה אותה לבנו, השיר החותם והעצוב.'),
])

add(547, [
'''הפול ממנצ׳סטר (אלבום 434) היו תמיד הלהקה של אדם אחד: מארק אי. סמית׳, זמר זועף וחכם שהחליף נגנים בקצב מסחרר. באמצע שנות השמונים הצטרפה ללהקה אשתו האמריקאית, בריקס סמית׳, גיטריסטית שאהבה פופ ומנגינות, והיא הביאה לצליל הקשה של הלהקה גם פזמונים. This Nation's Saving Grace, שיצא ב־1985, נחשב בעיני רבים לאלבום הטוב ביותר שלהם.''',
'''המוזיקה עדיין חוזרת ועקשנית, עם בס מהפנט, גיטרות צורמות ותופים יבשים, אבל עכשיו יש בה גם קליטות ושמחה. סמית׳ מדבר־שר בקולו הצפוני והמתלונן, עם מילים מלאות הומור שחור, לעג ודימויים מוזרים. I Am Damo Suzuki הוא מחווה לזמר של להקת קאן הגרמנית (אלבומים 220 ו־278), עם קצב שחוזר כמו מכונה. Bombast, הפותח, מהיר ותוקפני, ו־What You Need קליט ומקפץ, בזכות הגיטרה של בריקס. Spoilt Victorian Child מהיר ומשעשע, ו־L.A. הוא קטע מוזר ומהפנט על העיר האמריקאית, עם תופים אלקטרוניים.''',
'''האלבום הראה שהפול יכולים להיות גם נגישים, בלי לאבד את המוזרות שלהם. סמית׳ המשיך להקליט עוד עשרות אלבומים, עם עשרות נגנים, עד מותו ב־2018, והלהקה השפיעה על דורות של מוזיקאים בריטים, ממוזיקת אינדי ועד מוזיקה אלקטרונית. הבס של סטיב הנלי והגיטרה של בריקס בונים יחד קיר צפוף של צליל.''',
'''אם אהבתם את Live at the Witch Trials (אלבום 434), שמעו כאן איך אותה להקה נשמעת כמעט שבע שנים אחר כך. ואם אתם מכירים את קאן, התחילו ב־I Am Damo Suzuki.''',
], [
('I Am Damo Suzuki', 'מחווה לזמר של קאן, עם קצב חוזר ומהפנט כמו מכונה.'),
('What You Need', 'שיר קליט ומקפץ, בזכות הגיטרה והחוש למנגינות של בריקס סמית׳.'),
('Spoilt Victorian Child', 'שיר מהיר ומשעשע על ילד מפונק, עם הקול המתלונן והציני של סמית׳.'),
])

add(548, [
'''עבדאללה איברהים, שנקרא בצעירותו דולר בראנד, נולד בקייפטאון שבדרום אפריקה וגדל על מזמורי כנסייה, מוזיקה מלאית, ג׳אז אמריקאי ומוזיקת הרחוב של העיירות השחורות. בתחילת שנות השישים, בשיא משטר האפרטהייד, הוא עזב לאירופה, ושם פגש את דיוק אלינגטון (אלבום 6), שעזר לו להקליט את האלבום הראשון שלו מחוץ לאפריקה. Water from an Ancient Well, עם הרכב בן שבעה נגנים בשם Ekaya, יצא באמצע שנות השמונים, כשעדיין חי בגלות.''',
'''המוזיקה שקטה, חמה ומלאת געגועים: פסנתר עדין, סקסופונים וחצוצרה שמנגנים יחד מנגינות פשוטות כמו מזמורים, ובס וקצב שמזכירים את המוזיקה העממית של דרום אפריקה. אין כאן ג׳אז מהיר ומסובך, אלא מנגינות שאפשר כמעט לשיר. Mandela הוא מחווה לנלסון מנדלה, שישב אז בכלא, עם מנגינה חגיגית ונחושה. Song for Sathima נכתב לאשתו, הזמרת סאתימה בי בנג׳מין, והוא בלדה רכה. שיר הנושא איטי ומהורהר, ו־The Wedding הוא מזמור חגיגי ושמח, כמו תהלוכה בכפר.''',
'''איברהים חזר לדרום אפריקה אחרי סוף האפרטהייד, ובטקס ההשבעה של מנדלה לנשיא, ב־1994, הוא ניגן. Water from an Ancient Well נחשב לאחד האלבומים היפים של הג׳אז הדרום אפריקאי, ושל המוזיקה של הגלות. השיר Manenberg שלו, מאמצע שנות השבעים, נחשב בדרום אפריקה להמנון של המאבק באפרטהייד.''',
'''זה אלבום ליום שקט. שמעו את Mandela ואת The Wedding, ואחר כך את Home Is Where the Music Is של יו מסקלה (אלבום 252), עוד מוזיקאי שגלה מאותה ארץ.''',
], [
('Mandela', 'מחווה לנלסון מנדלה שישב בכלא, עם מנגינה חגיגית ונחושה.'),
('Song for Sathima', 'בלדה רכה לאשתו הזמרת סאתימה, בפסנתר עדין וסקסופון חם ומלטף.'),
('The Wedding', 'מזמור חגיגי ושמח, כמו תהלוכת חתונה בכפר עם כל כלי הנשיפה.'),
])

add(549, [
'''a-ha היו שלושה צעירים מנורווגיה: הזמר מורטן הארקט, בעל קול שיכול לעלות לגבהים מדהימים, הקלידן מגנה פורוהולמן והגיטריסט פאל וואקטאר. הם עברו ללונדון כדי להצליח, גרו בדירות קטנות וניסו שוב ושוב. Take On Me, השיר שלהם, יצא פעמיים ונכשל, עד שבפעם השלישית צולם לו קליפ מיוחד, שבו צעירה נשאבת לתוך חוברת קומיקס מצוירת בעיפרון. השיר הגיע למקום הראשון באמריקה, והאלבום Hunting High and Low יצא ב־1985.''',
'''המוזיקה היא סינת־פופ רומנטי וגדול: סינתיסייזרים מבריקים, תופים אלקטרוניים, כלי מיתר, והקול של הארקט, שעובר מנמוך לגבוה בקלות. Take On Me, עם ריף הקלידים הקופצני, הוא שיר חיזור נלהב, והקפיצה של הארקט לצליל הגבוה בפזמון היא מהמפורסמות בפופ. The Sun Always Shines on T.V. דרמטי וכבד יותר, עם מקהלה ותזמורת. שיר הנושא הוא בלדה גדולה ונוגה על חיפוש אחר אהבה, ו־Train of Thought מתאר אדם שבוי בשגרה של רכבת ומשרד.''',
'''a-ha הפכו לאחת הלהקות המצליחות בעולם באמצע שנות השמונים, ובמיוחד בנורווגיה, שבה הם גיבורים לאומיים. הקליפ של Take On Me נחשב לאחד הקליפים החשובים בתולדות התחום, והשיר ממשיך להיות מושמע בכל מקום. הם כתבו בהמשך גם שיר לסרט של ג׳יימס בונד. פורוהולמן הפך בהמשך גם לצייר ולאמן מוכר בנורווגיה.''',
'''שמעו את Take On Me, ושימו לב לקפיצה בפזמון. אחר כך שמעו את The Sun Always Shines on T.V., ותגלו להקה עמוקה יותר ממה שנדמה.''',
], [
('Take On Me', 'שיר חיזור נלהב, עם ריף קלידים קופצני וקפיצה גבוהה בפזמון.'),
('The Sun Always Shines on T.V.', 'דרמטי וכבד, עם מקהלה ותזמורת, על בדידות מול מסך הטלוויזיה.'),
('Hunting High and Low', 'בלדה גדולה ונוגה על חיפוש אחר אהבה, עם כלי מיתר וקול גבוה.'),
])

add(550, [
'''רולנד אורזבל וקרט סמית׳ גדלו בבאת׳ שבאנגליה, ושניהם עברו ילדות קשה. הם קראו לצמד שלהם Tears for Fears, "דמעות במקום פחדים", על שם רעיון של פסיכולוג אמריקאי, שטען שאנשים צריכים לצעוק ולבכות את הכאבים של ילדותם. אחרי אלבום ראשון קודר ומצליח, הם הקליטו את Songs from the Big Chair עם המפיק כריס יוז, לשעבר אחד המתופפים של אדם והאנטס (אלבום 454). האלבום יצא ב־1985.''',
'''הצליל גדול ומלוטש: סינתיסייזרים, גיטרות, תופים עוצמתיים, פסנתר וסקסופון, והשירים ארוכים ובנויים בקפידה. Shout הוא המנון של זעם וקריאה לשחרר את מה שבפנים, עם פזמון שמתאים לאצטדיון. Everybody Wants to Rule the World, הלהיט הגדול, הוא שיר רגוע ושמשי, בקצב מתנדנד, על הרצון של כולם לשלוט ועל המחיר שלו. הוא הגיע למקום הראשון באמריקה. Head over Heels הוא שיר אהבה רומנטי ונבוך, עם פסנתר יפה, ו־Mothers Talk מהיר ועצבני. The Working Hour נפתח בסקסופון ארוך ומלנכולי.''',
'''האלבום נמכר במיליוני עותקים, והפך את הצמד לכוכבים בכל העולם. השם לקוח מסרט טלוויזיה על אישה עם הפרעה נפשית, שהרגישה בטוחה רק בכיסא גדול. כך גם השירים: מאחורי הפופ המבריק מסתתרים שאלות קשות על כוח, על פחד ועל ילדות. רוב השירים כתב אורזבל, וחלקם שר סמית׳, כמו Everybody Wants to Rule the World.''',
'''שמעו את Everybody Wants to Rule the World בנסיעה, ואחר כך את Shout בעוצמה גבוהה. שני צדדים של אותו צמד, הרגוע והזועם.''',
], [
('Everybody Wants to Rule the World', 'שיר רגוע ושמשי על הרצון של כולם לשלוט, מקום ראשון באמריקה.'),
('Shout', 'המנון של זעם וקריאה לשחרר את מה שבפנים, עם פזמון של אצטדיון.'),
('Head Over Heels / Broken', 'שיר אהבה רומנטי ונבוך על התאהבות עמוקה, עם פסנתר יפה.'),
])

add(551, [
'''דייר סטרייטס, להקה בריטית שהוביל הגיטריסט והזמר מארק נופלר, הצליחו כבר בסוף שנות השבעים עם Sultans of Swing, בזכות נגינה עדינה ומדויקת וקול רגוע. נופלר גם כתב לאחרים, כמו את Private Dancer של טינה טרנר (אלבום 541). Brothers in Arms, שהוקלט באי מונטסראט שבים הקריבי, באותו אולפן של הפוליס (אלבום 529), יצא ב־1985.''',
'''הצליל נקי ומבריק במיוחד, כי האלבום הוקלט בטכנולוגיה דיגיטלית, והוא היה מהאלבומים הראשונים שנמכרו בכמויות עצומות בדיסק. Money for Nothing, עם ריף גיטרה כבד ומפורסם, מסופר מפי פועל שמוביל מקררים וטלוויזיות, ורואה בקנאה כוכבי רוק בטלוויזיה, "כסף בשביל כלום". סטינג שר בו בקולות הרקע. Walk of Life הוא שיר שמח עם אורגן קופצני על נגן רחוב, ו־So Far Away, הפותח, עוסק באהבה מרחוק. Your Latest Trick נפתח בסקסופון לילי ורך, ושיר הנושא, שחותם, הוא בלדה איטית ועצובה על חיילים במלחמה, עם גיטרה שבוכה.''',
'''Brothers in Arms נמכר בעשרות מיליוני עותקים, והפך לאחד האלבומים הנמכרים בתולדות בריטניה. הקליפ של Money for Nothing, עם דמויות מונפשות במחשב, היה חדשני מאוד. האלבום עזר להפוך את הדיסק לפורמט הפופולרי של המוזיקה. הלהקה יצאה אחריו לסיבוב הופעות ענק בכל העולם, ואחריו לקחה הפסקה של כמה שנים. נופלר כתב בהמשך גם פסקולים לסרטים, ונחשב לאחד הגיטריסטים העדינים והמוכרים בעולם.''',
'''שמעו אותו במערכת שמע טובה, הוא נבנה בדיוק בשביל זה. התחילו ב־Your Latest Trick, ואחר כך שיר הנושא, בשקט.''',
], [
('Money for Nothing', 'פועל שמקנא בכוכבי רוק בטלוויזיה, עם ריף גיטרה כבד ומפורסם.'),
('Your Latest Trick', 'פתיחה בסקסופון לילי ורך, ושיר עצוב על אהבה שנגמרת ועל תרגיל אחרון.'),
('Brothers in Arms', 'בלדה איטית ועצובה על חיילים במלחמה, עם גיטרה שבוכה.'),
])
